using System.Collections;
using System.Net.Http;
using System.Data;
using Niedax.AzureRelayHelper.RicoKalk;
using Niedax.AzureServiceBus.Models.RicoKalk;

using Niedax.AzureServiceBus.Models.RicoKalk.Relay;
using Niedax.AzureSecurityHelper.KeyVault.RicoKalk;
using Niedax.AdoNS.RicoKalk;
using Niedax.General;
using Niedax.General.Sql;


/// <summary>
/// PaffH 22.12.23
/// </summary>
public class NDXKBVBuildingProject2RicoKalk
{
    NDXRicoKalk2KBVBuildingProjectContract nDXRicoKalk2KBVBuildingProjectContract;
    KCS_KBVBuildingProjectTable kBV_BuildingProjectTable;
    NDX_KBV2RicoKalkMap nDX_KBV2RicoKalkMap;
    NDX_KBV2RicoProtTable nDX_KBV2RicoProtTable;
    NDX_KBV2RicoProtLine nDX_KBV2RicoProtLine;

    DataAreaId masterCompany;
    KCS_KBVRelationID kBVRelationIdPlaner;
    boolean lDoRicoKalkPublicate;
    boolean lTestEnvironment;
    boolean lInfoRicoKalkSyncInit;
    boolean lInfoRicoKalkSync;          // Informationsanzeige beim sync. mit RicoKalk
    container conRicoUK = conNull();
    NDXRicoKalkDatabase ricoKalkDatabase;
    NDXKBVBuildingProject2RicoKalkProt oProtInfo;
    int nrIstAnfrage;   // aktuelle / neue Anfrage-Nr. aus RicoKalk
    NDXRicoKalkBVNr bvNrRicoKalk;
    FormRun callerForm;
    boolean lRicoRequest;       // Rico-Anfrage im aktuellen BV?
    boolean lIsInBatch;

    boolean mocking = true;
    ADORicoKalk ado;
    NDXRicoKalkADO  nDXRicoKalkADO;
    KeyVaultGetSecretRelayBVRico keyVaultGetSecretRelay;
    NDXUserIdRico userIdRico;
    TimeOfDay startPublicateSeconds;
    boolean lRicoSyncRequiered;         // ist eine Synchronisierung mit Rico erforderlich?
    NDXMailerRicoKalk oErrorMail;

}

