/// <summary>
/// PaffH 06.02.25
/// </summary>
/// <returns>classname</returns>
public str Name()
{
    return classId2Name(classIdGet(this));
}

public FormRun parmCallerForm()
{
    return callerForm;
}

/// <summary>
/// PaffH 22.12.23
/// </summary>
/// <param name = "args">Args</param>
protected void new(Args args = null)
{
    lIsInBatch = true;
    oErrorMail = NDXMailerRicoKalk::construct(true, lIsInBatch);
    KCS_KBVParameters kCS_KBVParameters = KCS_KBVParameters::find();
    masterCompany = kCS_KBVParameters.KCS_DataAreaName;
    kBVRelationIdPlaner = kCS_KBVParameters.KCS_KBVRelationID1;
    lDoRicoKalkPublicate = kCS_KBVParameters.NDXKBVPublicate2RicoKalk == NoYes::Yes;
    lTestEnvironment = kCS_KBVParameters.NDXTestEnvironment == NoYes::Yes;

    conRicoUK += kCS_KBVParameters.AVADataAreaIdRICO;

    ricoKalkDatabase = lTestEnvironment ? NDXRicoKalkConstants::DataBaseTest : NDXRicoKalkConstants::DataBaseLive;
    if(lDoRicoKalkPublicate == true)
    {
        oProtInfo = NDXKBVBuildingProject2RicoKalkProt::construct();
        this.initializeADO();
    }

    if (args)
    {
        if (!(args.object() is NDXRicoKalk2KBVBuildingProjectContract))
        {
            throw new System.Exception(Error::wrongUseOfFunction(funcName()));
        }
        nDXRicoKalk2KBVBuildingProjectContract = args.object() as NDXRicoKalk2KBVBuildingProjectContract;
    }
}

/// <summary>
/// PaffH 27.01.24
/// </summary>
/// <param name = "_timeOfDay">TimeOfDay</param>
/// <returns>TimeOfDay</returns>
public TimeOfDay parmStartPublicateSeconds(TimeOfDay _timeOfDay = startPublicateSeconds)
{
    TimeOfDay timeOfDayLoc = _timeOfDay;
    if (prmIsDefault(_timeOfDay) && !startPublicateSeconds)
    {
        timeOfDayLoc = NDXHelperCommon::timeNow();
    }
    startPublicateSeconds = timeOfDayLoc;
    return startPublicateSeconds;
}

/// <summary>
/// PaffH 12.02.24
/// </summary>
/// <param name = "_lRicoSyncRequiered">boolean</param>
/// <returns>boolean</returns>
boolean parmlRicoSyncRequiered(boolean _lRicoSyncRequiered = lRicoSyncRequiered)
{
    lRicoSyncRequiered  = _lRicoSyncRequiered;
    return lRicoSyncRequiered;
}

/// <summary>
/// PaffH 27.12.23
/// </summary>
/// <param name = "args">Args</param>
/// <returns>NDXKBVBuildingProject2RicoKalk</returns>
static NDXKBVBuildingProject2RicoKalk construct(Args args = null)
{
    return new NDXKBVBuildingProject2RicoKalk(args);
}

/// <summary>
/// PaffH 27.12.23
/// </summary>
/// <param name = "_args">Args</param>
static void main(Args _args)
{
    NDXKBVBuildingProject2RicoKalk::publicate2RicoKalkAsync(_args);
}

/// <summary>
/// PaffH 09.02.24
/// last modified: PaffH 16.12.24
/// </summary>
/// <param name = "_kCS_KBVBuildingProjectTable">KCS_KBVBuildingProjectTable</param>
void checkRicoKalkPublicate(KCS_KBVBuildingProjectTable _kCS_KBVBuildingProjectTable)
{
    if (this.parmLRicoRequest() || this.parmlRicoSyncRequiered())   // building project with Rico-request
    {
        // additional check: there must be at least 1 Rico request for publication
        KCS_KBVRequestTable kCS_KBVRequestTableLocal;
        select firstonly crosscompany:conRicoUk RecId from kCS_KBVRequestTableLocal
            where kCS_KBVRequestTableLocal.KCS_KBVBuildingProjectID == _kCS_KBVBuildingProjectTable.KCS_KBVBuildingProjectID;
        if (kCS_KBVRequestTableLocal.RecId == 0)
        {
            //Error(strFmt("@NDXRicoBV:NDXRicoTransferWithoutRicoRequest", _kCS_KBVBuildingProjectTable.KCS_KBVBuildingProjectID));
            this.parmLRicoRequest(false);
            this.parmlRicoSyncRequiered(false);
            return;
        }
        boolean lDoPublicate = !this.parmLInfoRicoKalkSync() ||
            (Box::yesNo(strFmt("@NDXRicoBV:NDXAdjustBVInformationWithRicoKalk", _kCS_KBVBuildingProjectTable.KCS_KBVBuildingProjectID), DialogButton::Yes) == DialogButton::Yes);
        // PaffH 23.07.24 leave Record - event is fired twice!
        this.parmLRicoRequest(false);
        this.parmlRicoSyncRequiered(false);
        if (lDoPublicate)
        {
            MenuFunction menuFunction = new MenuFunction(menuItemActionStr(NDXKBVBuildingProject2RicoKalk), MenuItemType::Action);
            if (menuFunction && menuFunction.checkAccessRights())
            {
                Args args = new Args();
                args.record(_kCS_KBVBuildingProjectTable);
                menuFunction.run(args);
            }
        }
    }
}

/// <summary>
/// PaffH 09.02.24
/// </summary>
/// <param name = "_lRicoRequest">boolean</param>
/// <returns>lRicoRequest</returns>
public boolean parmLRicoRequest(boolean _lRicoRequest = lRicoRequest)
{
    lRicoRequest = _lRicoRequest;
    return lRicoRequest;
}

/// <summary>
/// PaffH 09.02.24
/// </summary>
/// <param name = "_kCS_KBVBuildingProjectID">_kCS_KBVBuildingProjectID</param>
/// <returns>container</returns>
public container doRicoKalkPublicate(KCS_KBVBuildingProjectID _kCS_KBVBuildingProjectID)
{
    boolean lDoRicoKalkPublicateUK = lDoRicoKalkPublicate;
    if (lDoRicoKalkPublicateUK)
    {
        KCS_KBVRequestTable kCS_KBVRequestTable;
        select firstonly crosscompany:conRicoUK kCS_KBVRequestTable
            where kCS_KBVRequestTable.KCS_KBVBuildingProjectID == _kCS_KBVBuildingProjectID;
        lDoRicoKalkPublicateUK = (kCS_KBVRequestTable != null);
    }
    return [lDoRicoKalkPublicateUK, lDoRicoKalkPublicate, conPeek(conRicoUK, 1)];
}

/// <summary>
/// PaffH 29.01.24
/// </summary>
/// <param name = "_args">Args</param>
/// <returns>container</returns>
public static container publicate2RicoKalkAsync(Args _args)
{
    KCS_KBVBuildingProjectTable  kBV_BuildingProjectTable = _args.record();
    KCS_KBVBuildingProjectID kBVBuildingProjectID = kBV_BuildingProjectTable.KCS_KBVBuildingProjectID;
    //container conTable = kBV_BuildingProjectTable.buf2con();
    Global::runAsync(
        classNum(NDXKBVBuildingProject2RicoKalk),
        staticMethodStr(NDXKBVBuildingProject2RicoKalk, publicate2RicoKalkFromCon),
        [kBV_BuildingProjectTable, kBVBuildingProjectID],
        System.Threading.CancellationToken::None,
        classNum(NDXKBVBuildingProject2RicoKalk),
        staticMethodStr(NDXKBVBuildingProject2RicoKalk, publicate2RicoKalkResult)
        );
    return (['']);
}

/// <summary>
/// PaffH 29.01.24
/// </summary>
/// <param name = "_result">AsyncTaskResult</param>
public static void publicate2RicoKalkResult(AsyncTaskResult _result)
{
    //container returnValue = _result.getResult();
    boolean taskSucceed = conPeek(_result.getResult(), 1);
    boolean lInfoRicoKalkSync = conPeek(_result.getResult(), 2);
    str infoLogAsStr = NDXHelperCommon::infoStrFromAsyncTaskResult(_result);
    if (!taskSucceed)
    {
        Error(infoLogAsStr);
    }
    else if (lInfoRicoKalkSync)
    {
        info(infoLogAsStr);
    }
}

/// <summary>
/// PaffH 27.12.23
/// modified: 14.11.24
/// </summary>
protected void initializeADO()
{
    changecompany(conPeek(conRicoUK, 1))
    {
        ado = new ADORicoKalk(mocking);
        keyVaultGetSecretRelay = new KeyVaultGetSecretRelayBVRico();
        keyVaultGetSecretRelay.KeyVaultValue = NDXKeyVaultHelper::GetKeyVaultSecretValueFromD365FO(KCS_KBVParameters::find().NDXKeyVaultSecretNameConnectionStringAzureRelayD365FO, "@NDXRicoBV:NDXMissingEntryKeyVaultSecretNameRelay");
        if (keyVaultGetSecretRelay.KeyVaultValue == null)
        {
            error("@NDX:NDXErrorInitADOConnectionStringAzureRelay");
        }
        else
        {
            nDXRicoKalkADO = NDXRicoKalkADO::construct(ado, keyVaultGetSecretRelay, mocking);
        }
    }
}

/// <summary>
/// PaffH 27.12.23
/// modified: PaffH 15.11.24
/// AX2009: classes.NDX_KBVBuildingProject2RicoKalk.parmLInfoRicoKalkSync()
/// </summary>
/// <param name = "_lInfoRicoKalkSync">boolean</param>
/// <returns>boolean</returns>
boolean parmLInfoRicoKalkSync(boolean _lInfoRicoKalkSync = lInfoRicoKalkSync)
{
    lInfoRicoKalkSync = _lInfoRicoKalkSync;
    if (prmisdefault(_lInfoRicoKalkSync) && !lInfoRicoKalkSyncInit)
    {
        NDXPrivilegeNoRicoKalkTransferInfo privilege = KCS_KBVParameters::find().NDXPrivilegeNoRicoKalkTransferInfo;
        if (!privilege)
        {
            error(strfmt("@NDXBase:NDXFillFieldInTable", tableId2Name(tableNum(KCS_KBVParameters)), fieldstr(KCS_KBVParameters, NDXPrivilegeNoRicoKalkTransferInfo)));
            const str privilegeDefault = 'NDXRicoKalkTransferWithoutInfo';
            warning(strFmt("@NDXBase:NDXDefaultValueIsApplied", privilegeDefault));
            privilege = privilegeDefault;
        }
        lInfoRicoKalkSync = xUserInfo::isSysAdmin() || !NDXHelperSecurity::hasUserSecurityPrivilege(privilege);
        lInfoRicoKalkSyncInit = true;
    }
    return lInfoRicoKalkSync;
}

/// <summary>
/// PaffH 27.12.23
/// update RicoKalk::KalkBVKopf
/// AX2009: classes.NDX_KBVBuildingProject2RicoKalk.updateKalkBVKopf()
/// </summary>
/// <returns>boolean success</returns>   
protected boolean updateKalkBVKopf()
{
    oProtInfo.parmProtID2(NDXRicoKalkConstants::BV_Kopf);
    if (this.parmLInfoRicoKalkSync())
    {
        Info("@NDXRicoBV:NDXTransferBVKopf");
    }
    bvNrRicoKalk = nDXRicoKalkADO.selectBVNrFromTblKalkBVKopf(
        nDX_KBV2RicoKalkMap.RicoKalkBVNr, 
        false, 
        strFmt("@NDXRicoBV:NDXRicoKalkBuildingProjectTransfer", nDX_KBV2RicoKalkMap.KBVBuildingProjectID, nDX_KBV2RicoKalkMap.RicoKalkBVNr));
    if (!bvNrRicoKalk)
    {
        // insert new record in RicoKalk.tblKalkBVKopf
        bvNrRicoKalk = nDXRicoKalkADO.insertKalkBVKopf(nDX_KBV2RicoKalkMap.RicoKalkBVNr, false);
    }

    // get information from tblKalkBVKopf
    TblKalkBVKopf tblKalkBVKopf = nDXRicoKalkADO.selectFromTblKalkBVKopf(bvNrRicoKalk, false);
    if (!tblKalkBVKopf)
    {
        throw(Error(strFmt("@NDXRicoBV:NDXDataTransfertoRicoKalkNotSuccessful", bvNrRicoKalk)));
    }

    char c1 = subStr(kBV_BuildingProjectTable.KCS_KBVSubject, NDXRicoKalkConstants::BezFieldLength, 1);
    char c2 = subStr(kBV_BuildingProjectTable.KCS_KBVSubject, NDXRicoKalkConstants::BezFieldLength + 1, 1);
    int lastStringTokenPos = 0;
    if (c1 != '' && c2 != '' && c1 != ' ' && c2 != ' ')
    {
        lastStringTokenPos = strFind(kBV_BuildingProjectTable.KCS_KBVSubject, ' ', NDXRicoKalkConstants::BezFieldLength, -NDXRicoKalkConstants::BezFieldLength);
    }

    // Bez1, Bez2
    NDXRicoBVBezeichnung nDXRicoBVBezeichnung1, nDXRicoBVBezeichnung2;
    if (lastStringTokenPos > 0)
    {
        nDXRicoBVBezeichnung1 = subStr(kBV_BuildingProjectTable.KCS_KBVSubject, 1, lastStringTokenPos);
        nDXRicoBVBezeichnung2 = subStr(kBV_BuildingProjectTable.KCS_KBVSubject, lastStringTokenPos + 1, strLen(kBV_BuildingProjectTable.KCS_KBVSubject));
    }
    else
    {
        nDXRicoBVBezeichnung1 = subStr(kBV_BuildingProjectTable.KCS_KBVSubject, 1, NDXRicoKalkConstants::BezFieldLength);
        nDXRicoBVBezeichnung2 = subStr(kBV_BuildingProjectTable.KCS_KBVSubject, NDXRicoKalkConstants::BezFieldLength + 1, strLen(kBV_BuildingProjectTable.KCS_KBVSubject));
    }
    oProtInfo.add(NDXKBVProtDetail::KalkBVKopf_Bez1,
        tblKalkBVKopf.Bez1, nDXRicoBVBezeichnung1,
        tblKalkBVKopf.Bez1, nDXRicoBVBezeichnung1, NDXRicoKalkTblKalkBVKopfConstants::Bez1, true);
    oProtInfo.add(NDXKBVProtDetail::KalkBVKopf_Bez2,
        tblKalkBVKopf.Bez2, nDXRicoBVBezeichnung2,
        tblKalkBVKopf.Bez2, nDXRicoBVBezeichnung2, NDXRicoKalkTblKalkBVKopfConstants::Bez2);

    // created by user
    oProtInfo.add(NDXKBVProtDetail::KalkBVKopf_UserAngelegt,
        tblKalkBVKopf.UserAngelegt_IDBound, oProtInfo.getMappedRicoKalkUser(kBV_BuildingProjectTable.KCS_KBVCreatedBy),
        tblKalkBVKopf.UserAngelegt_IDBound, oProtInfo.getMappedRicoKalkUser(kBV_BuildingProjectTable.KCS_KBVCreatedBy), NDXRicoKalkTblKalkBVKopfConstants::UserAngelegt_IDBOUND);

    // country
    int Land_IdBound = NDX_RicoKalkMapping::getMappedCountryRegionId(kBV_BuildingProjectTable.AddressCountryRegionId, tblKalkBVKopf.Land_IdBound);
    oProtInfo.add(NDXKBVProtDetail::KalkBVKopf_LandID,
        tblKalkBVKopf.Land_IdBound, Land_IdBound,
        int2Str(tblKalkBVKopf.Land_IdBound), int2Str(Land_IdBound), NDXRicoKalkTblKalkBVKopfConstants::Land_IdBound);

    // location
    int NL_IdBound = 1;
    oProtInfo.add(NDXKBVProtDetail::KalkBVKopf_Niederlassung,
        tblKalkBVKopf.NL_IDBOUND, NL_IdBound,
        int2Str(tblKalkBVKopf.NL_IDBOUND), int2Str(NL_IdBound), NDXRicoKalkTblKalkBVKopfConstants::NL_IDBOUND);

    // 1.LV-Pos
    if (strLen(kBV_BuildingProjectTable.KCS_KBVTenderFirstPosition) > NDXRicoKalkConstants::LVPOSELength)
    {
        warning(strFmt("@NDXRicoBV:NDXFieldContentsInRicoKalkIsTruncated",
            NDXRicoKalkConstants::LVPOSE,
            NDXRicoKalkConstants::LVPOSELength,
            subStr(kBV_BuildingProjectTable.KCS_KBVTenderFirstPosition, NDXRicoKalkConstants::LVPOSELength, strLen(kBV_BuildingProjectTable.KCS_KBVTenderFirstPosition))
            ));
    }
    oProtInfo.add(NDXKBVProtDetail::KalkBVKopf_LVPosFirst,
        tblKalkBVKopf.LVPOSE, subStr(kBV_BuildingProjectTable.KCS_KBVTenderFirstPosition, 1, NDXRicoKalkConstants::LVPOSELength),
        tblKalkBVKopf.LVPOSE, subStr(kBV_BuildingProjectTable.KCS_KBVTenderFirstPosition, 1, NDXRicoKalkConstants::LVPOSELength), NDXRicoKalkTblKalkBVKopfConstants::LVPOSE);

    // 1.LV-Pos quantity
    oProtInfo.add(NDXKBVProtDetail::KalkBVKopf_LVPosFirstMenge,
        tblKalkBVKopf.MengeLVPosE, kBV_BuildingProjectTable.KCS_KBVTenderFirstPositionQty,
        num2Str(tblKalkBVKopf.MengeLVPosE, 0, 2, DecimalSeparator::Comma, ThousandSeparator::Dot), 
        num2Str(kBV_BuildingProjectTable.KCS_KBVTenderFirstPositionQty, 0, 2, DecimalSeparator::Comma, ThousandSeparator::Dot), NDXRicoKalkTblKalkBVKopfConstants::MengeLVPosE);

    // last LV-Pos (don't exists anymore)
    // last LV-Pos quantity (don't exists anymore)

    // BV-Art
    int BVArt_IdBound = nDXRicoKalkADO.checkBVKlasse(kBV_BuildingProjectTable.KCS_KBVClassID, false);
    oProtInfo.add(NDXKBVProtDetail::KalkBVKopf_BVArt,
        tblKalkBVKopf.BVArt_IdBound, BVArt_IdBound,
        int2Str(tblKalkBVKopf.BVArt_IdBound), int2Str(BVArt_IdBound), NDXRicoKalkTblKalkBVKopfConstants::BVArt_IdBound);

    // BV-number Niedax
    oProtInfo.add(NDXKBVProtDetail::KalkBVKopf_BVNr_Niedax,
        tblKalkBVKopf.BVNR_Niedax, str2Int(kBV_BuildingProjectTable.KCS_KBVBuildingProjectID),
        int2Str(tblKalkBVKopf.BVNR_Niedax), int2Str(str2Int(kBV_BuildingProjectTable.KCS_KBVBuildingProjectID)), NDXRicoKalkTblKalkBVKopfConstants::BVNR_Niedax);

    // ZIP
    oProtInfo.add(NDXKBVProtDetail::KalkBVKopf_PLZ,
        tblKalkBVKopf.PLZ, kBV_BuildingProjectTable.AddressZipCodeId,
        tblKalkBVKopf.PLZ, kBV_BuildingProjectTable.AddressZipCodeId, NDXRicoKalkTblKalkBVKopfConstants::PLZ);

    // City
    oProtInfo.add(NDXKBVProtDetail::KalkBVKopf_Ort,
        tblKalkBVKopf.Ort, kBV_BuildingProjectTable.AddressCity,
        tblKalkBVKopf.Ort, kBV_BuildingProjectTable.AddressCity, NDXRicoKalkTblKalkBVKopfConstants::Ort);

    // Street
    oProtInfo.add(NDXKBVProtDetail::KalkBVKopf_Strasse,
        tblKalkBVKopf.Strasse, kBV_BuildingProjectTable.AddressStreet,
        tblKalkBVKopf.Strasse, kBV_BuildingProjectTable.AddressStreet, NDXRicoKalkTblKalkBVKopfConstants::Strasse);

    // date created
    oProtInfo.add(NDXKBVProtDetail::KalkBVKopf_DatumAngelegt,
        tblKalkBVKopf.DatumAngelegt, kBV_BuildingProjectTable.KCS_KBVCreatedDate,
        date2Str(tblKalkBVKopf.DatumAngelegt, 123, DateDay::Digits2, DateSeparator::Dot, DateMonth::Digits2, DateSeparator::Dot, DateYear::Digits4), 
        date2Str(kBV_BuildingProjectTable.KCS_KBVCreatedDate, 123, DateDay::Digits2, DateSeparator::Dot, DateMonth::Digits2, DateSeparator::Dot, DateYear::Digits4), NDXRicoKalkTblKalkBVKopfConstants::DatumAngelegt);

    // date start of work
    oProtInfo.add(NDXKBVProtDetail::KalkBVKopf_DatumBaubeginn,
        tblKalkBVKopf.DatumBaubegin, kBV_BuildingProjectTable.KCS_KBVStartOfWork,
        date2Str(tblKalkBVKopf.DatumBaubegin, 123, DateDay::Digits2, DateSeparator::Dot, DateMonth::Digits2, DateSeparator::Dot, DateYear::Digits4), 
        date2Str(kBV_BuildingProjectTable.KCS_KBVStartOfWork, 123, DateDay::Digits2, DateSeparator::Dot, DateMonth::Digits2, DateSeparator::Dot, DateYear::Digits4), NDXRicoKalkTblKalkBVKopfConstants::DatumBaubegin);


    if (oProtInfo.write(this, ado))
    {
        nDXRicoKalkADO.updateFromKalkBVKopf(bvNrRicoKalk, false);
    }

    return true;
}

/// <summary>
/// PaffH 11.01.24
/// update requests
/// </summary>
void updateRequests()
{
    if (!bvNrRicoKalk)
    {
        Error("@NDXRicoBV:NDXBVNumberRicoKalkUnknown");
        return;
    }
    TblKalkInterressent tblKalkInterressent;
    TblKalkInteressentenZuord tblKalkInteressentenZuord;
    boolean lNewAbruf;
    TblKalkKopf tblKalkKopf;
    TblKalkKopf tblKalkKopfNew;
    KCS_KBVRequestTable kCS_KBVRequestTable;
    NDXRicoInquiryTrackingStatus Verfolg_Status;

    Query q = new Query();
    q.allowCrossCompany(true);
    //if (KCS_KBVParameters::find().NDXTestEnvironment == NoYes::Yes && KCS_KBVParameters::find().NDXTestDataArea)
    //{
    //    q.addCompanyRange(KCS_KBVParameters::find().NDXTestDataArea);
    //}
    //else
    //{
    q.addCompanyRange(conPeek(conRicoUK, 1));
    //}
    QueryBuildDataSource qbdsKbvRequestTable = q.addDataSource(tableNum(KCS_KBVRequestTable));
    qbdsKbvRequestTable.addRange(fieldNum(KCS_KBVRequestTable, KCS_KBVBuildingProjectID)).value(queryValue(kBV_BuildingProjectTable.KCS_KBVBuildingProjectID));
    QueryRun qr = new QueryRun(q);
    while (qr.next())
    {   
        if (qr.changed(tableNum(KCS_KBVRequestTable)))
        {
            kCS_KBVRequestTable = qr.get(tableNum(KCS_KBVRequestTable));
        }
        oProtInfo.parmProtID2(kCS_KBVRequestTable.KCS_KBVRequestID);

        if (this.parmLInfoRicoKalkSync())
        {
            info(strFmt("@NDXRicoBV:NDXRequestAdjustment", NDXHelperCommon::seconds2Str(), kCS_KBVRequestTable.KCS_KBVRequestID));
        }
        tblKalkKopfNew = new TblKalkKopf();
        tblKalkKopfNew.UserAngelegt_IDBound = '';

        // get information from tblKalkKopf
        tblKalkKopf = nDXRicoKalkADO.selectFromTblKalkKopf(
            bvNrRicoKalk, 
            kCS_KBVRequestTable.KCS_KBVRequestID,
            false,
            strFmt("@NDXRicoBV:NDXRicoKalkRequestTransfer", nDX_KBV2RicoKalkMap.KBVBuildingProjectID, bvNrRicoKalk, kCS_KBVRequestTable.KCS_KBVRequestID)
            );
        lNewAbruf = (tblKalkKopf.Abruf == 0);
        Verfolg_Status = tblKalkKopf.Verfolg_Status;
        // AX2009: Verfolg_Datum       = kBV_BuildingProjectTable.KCS_KBVReminderDate ? kBV_BuildingProjectTable.KCS_KBVReminderDate : kCS_KBVRequestTable.KCS_KBVReceiptDate;
        //         Field kBV_BuildingProjectTable.KCS_KBVReminderDate doesn't exist anymore.
        tblKalkKopfNew.Verfolg_Datum = kCS_KBVRequestTable.KCS_KBVReceiptDate;

        if (!(tblKalkKopf.BVNr_IDBOUND && tblKalkKopf.KBVRequestID))
        {
            // create Inquiry
            tblKalkKopf = nDXRicoKalkADO.insertKalkKopf(bvNrRicoKalk, kCS_KBVRequestTable, false);
        }

        if (!tblKalkKopf.AbrufID)
        {
            tblKalkKopf = nDXRicoKalkADO.selectFromTblKalkKopf(bvNrRicoKalk, kCS_KBVRequestTable.KCS_KBVRequestID, false);
        }

        NDXRicoKalkInteressent nDXRicoKalkInteressent = this.updateAnfrager(kCS_KBVRequestTable, false);
        tblKalkInterressent = nDXRicoKalkADO.selectTblKalkInterressentFromIntId(nDXRicoKalkInteressent.Int_ID, false);
        if (lNewAbruf)
        {
            tblKalkInteressentenZuord = nDXRicoKalkADO.selectFromTblKalkInteressentenZuord(nDXRicoKalkInteressent, false);
            tblKalkKopfNew.Verfolg_Status = tblKalkInteressentenZuord.AbrufStat;
        }
        else
        {
            tblKalkKopfNew.Verfolg_Status = tblKalkKopf.Verfolg_Status;
        }
        tblKalkKopfNew.AbrufID = tblKalkKopf.AbrufID;

        tblKalkKopfNew.UserAngelegt_IDBound = (lNewAbruf || !tblKalkKopf.UserAngelegt_IDBound) ?
            NDXRicoKalkTblKalkKopfConstants::UserAngelegt_IDBOUNDVorgabe :
            tblKalkKopf.UserAngelegt_IDBound;

        tblKalkKopfNew.Preisliste_IDBOUND = (lNewAbruf || !tblKalkKopf.Preisliste_IDBOUND) ?
            nDXRicoKalkADO.GetRicoPreisListId(nDXRicoKalkInteressent.Int_ID, false) :
            tblKalkKopf.Preisliste_IDBOUND;

        tblKalkKopfNew.VNr_Idbound = (lNewAbruf || !tblKalkKopf.VNr_Idbound) ?
            nDXRicoKalkADO.getRicoVnr(nDXRicoKalkInteressent.Int_ID, false) :
            tblKalkKopf.VNr_Idbound;

        tblKalkKopfNew.MWST_IDBOUND = (lNewAbruf || !tblKalkKopf.MWST_IDBOUND) ?
            tblKalkInterressent.MWST_IDBOUND :
            tblKalkKopf.MWST_IDBOUND;

        tblKalkKopfNew.GrundRabatt = (lNewAbruf || !tblKalkKopf.GrundRabatt) ?
            tblKalkInterressent.GRRabatt :
            tblKalkKopf.GrundRabatt;

        tblKalkKopfNew.WKZ_BOUND = (lNewAbruf || !tblKalkKopf.WKZ_BOUND) ?
            tblKalkInterressent.WKZ_BOUND :
            tblKalkKopf.WKZ_BOUND;

        oProtInfo.add(NDXKBVProtDetail::Anfrage_IntAnspr_Id,
            tblKalkKopf.intAnspr_IDBOUND, nDXRicoKalkInteressent.Ansp_ID,
            int2Str(tblKalkKopf.intAnspr_IDBOUND), int2Str(nDXRicoKalkInteressent.Ansp_ID), NDXRicoKalkTblKalkKopfConstants::IntAnspr_IDBOUND, true);
        oProtInfo.add(NDXKBVProtDetail::Anfrage_Int_ID,
            tblKalkKopf.Int_IDBOUND, nDXRicoKalkInteressent.Int_ID,
            int2Str(tblKalkKopf.Int_IDBOUND), int2Str(nDXRicoKalkInteressent.Int_ID), NDXRicoKalkTblKalkKopfConstants::Int_IDBOUND);
        oProtInfo.add(NDXKBVProtDetail::Anfrage_Knr,
            tblKalkKopf.Knr_IDBOUND, nDXRicoKalkInteressent.Knr_ID,
            int2Str(tblKalkKopf.Knr_IDBOUND), int2Str(nDXRicoKalkInteressent.Knr_ID), NDXRicoKalkTblKalkKopfConstants::Knr_IDBOUND);
        oProtInfo.add(NDXKBVProtDetail::Anfrage_UserAngelegtID,
            tblKalkKopf.UserAngelegt_IDBound, tblKalkKopfNew.UserAngelegt_IDBound,
            tblKalkKopf.UserAngelegt_IDBound, tblKalkKopfNew.UserAngelegt_IDBound, NDXRicoKalkTblKalkKopfConstants::UserAngelegt_IDBOUND);
        oProtInfo.add(NDXKBVProtDetail::Anfrage_Name1,
            tblKalkKopf.Name1, nDXRicoKalkInteressent.Name,
            tblKalkKopf.Name1, nDXRicoKalkInteressent.Name, NDXRicoKalkTblKalkKopfConstants::Name1);
        oProtInfo.add(NDXKBVProtDetail::Anfrage_Name2,
            tblKalkKopf.Name2, nDXRicoKalkInteressent.Name2,
            tblKalkKopf.Name2, nDXRicoKalkInteressent.Name2, NDXRicoKalkTblKalkKopfConstants::Name2);

        boolean conwithContactPersonId;
        boolean concontactPersonFound;
        str conAnfrage_PLZ;
        str conAnfrage_Strasse;
        str conAnfrage_Ort;
        [conwithContactPersonId, concontactPersonFound, conAnfrage_PLZ, conAnfrage_Strasse, conAnfrage_Ort] = this.getContactPersonData(kCS_KBVRequestTable);
        if (!conwithContactPersonId || concontactPersonFound)
        {
            oProtInfo.add(NDXKBVProtDetail::Anfrage_PLZ,
                tblKalkKopf.PLZ, conAnfrage_PLZ,
                tblKalkKopf.PLZ, conAnfrage_PLZ, NDXRicoKalkTblKalkKopfConstants::PLZ);
            oProtInfo.add(NDXKBVProtDetail::Anfrage_Strasse,
                tblKalkKopf.Strasse, conAnfrage_Strasse,
                tblKalkKopf.Strasse, conAnfrage_Strasse, NDXRicoKalkTblKalkKopfConstants::Strasse);
            oProtInfo.add(NDXKBVProtDetail::Anfrage_Ort,
                tblKalkKopf.Ort, conAnfrage_Ort,
                tblKalkKopf.Ort, conAnfrage_Ort, NDXRicoKalkTblKalkKopfConstants::Ort);
        }
        oProtInfo.add(NDXKBVProtDetail::Anfrage_Telefon,
            tblKalkKopf.Telefon, nDXRicoKalkInteressent.Phone,
            tblKalkKopf.Telefon, nDXRicoKalkInteressent.Phone, NDXRicoKalkTblKalkKopfConstants::Telefon);
        oProtInfo.add(NDXKBVProtDetail::Anfrage_Fax,
            tblKalkKopf.Fax, nDXRicoKalkInteressent.Telefax,
            tblKalkKopf.Fax, nDXRicoKalkInteressent.Telefax, NDXRicoKalkTblKalkKopfConstants::Fax);
        oProtInfo.add(NDXKBVProtDetail::Anfrage_EMail,
            tblKalkKopf.EMail, nDXRicoKalkInteressent.EMail,
            tblKalkKopf.EMail, nDXRicoKalkInteressent.EMail, NDXRicoKalkTblKalkKopfConstants::EMail);
        oProtInfo.add(NDXKBVProtDetail::Anfrage_Sollabgabe,
            tblKalkKopf.Datum_Sollabgabe, kCS_KBVRequestTable.KCS_KBVDeliveryDate,
            date2Str(tblKalkKopf.Datum_Sollabgabe, 123, 2,-1,2,-1,4), date2Str(kCS_KBVRequestTable.KCS_KBVDeliveryDate, 123, 2,-1,2,-1,4), NDXRicoKalkTblKalkKopfConstants::Datum_Sollabgabe);
        oProtInfo.add(NDXKBVProtDetail::Anfrage_KundenReferenz,
            tblKalkKopf.BVNR_Int, kCS_KBVRequestTable.CustRef,
            tblKalkKopf.BVNR_Int, kCS_KBVRequestTable.CustRef, NDXRicoKalkTblKalkKopfConstants::BVNr_Int);
        oProtInfo.add(NDXKBVProtDetail::Anfrage_VerfolgStatus,
            tblKalkKopf.Verfolg_Status, tblKalkKopfNew.Verfolg_Status,
            int2Str(tblKalkKopf.Verfolg_Status), int2Str(tblKalkKopfNew.Verfolg_Status), NDXRicoKalkTblKalkKopfConstants::Verfolg_Status);
        oProtInfo.add(NDXKBVProtDetail::Anfrage_VerfolgDatum,
            tblKalkKopf.Verfolg_Datum, tblKalkKopfNew.Verfolg_Datum,
            date2Str(tblKalkKopf.Verfolg_Datum, 123, 2,-1,2,-1,4), date2Str(tblKalkKopfNew.Verfolg_Datum, 123, 2,-1,2,-1,4), NDXRicoKalkTblKalkKopfConstants::Verfolg_Datum);
        oProtInfo.add(NDXKBVProtDetail::Anfrage_Preisliste,
            tblKalkKopf.Preisliste_IDBOUND, tblKalkKopfNew.Preisliste_IDBOUND,
            int2Str(tblKalkKopf.Preisliste_IDBOUND), int2Str(tblKalkKopfNew.Preisliste_IDBOUND), NDXRicoKalkTblKalkKopfConstants::Preisliste_IDBound);
        oProtInfo.add(NDXKBVProtDetail::Anfrage_Vertreter,
            tblKalkKopf.VNr_Idbound, tblKalkKopfNew.VNr_Idbound,
            int2Str(tblKalkKopf.VNr_Idbound), int2Str(tblKalkKopfNew.VNr_Idbound), NDXRicoKalkTblKalkKopfConstants::VNr_Idbound);
        oProtInfo.add(NDXKBVProtDetail::Anfrage_MwSt,
            tblKalkKopf.MWST_IDBOUND, tblKalkKopfNew.MWST_IDBOUND,
            int2Str(tblKalkKopf.MWST_IDBOUND), int2Str(tblKalkKopfNew.MWST_IDBOUND), NDXRicoKalkTblKalkKopfConstants::MWST_IDBOUND);
        oProtInfo.add(NDXKBVProtDetail::Anfrage_WKZ,
            tblKalkKopf.WKZ_BOUND, tblKalkKopfNew.WKZ_BOUND,
            tblKalkKopf.WKZ_BOUND, tblKalkKopfNew.WKZ_BOUND, NDXRicoKalkTblKalkKopfConstants::WKZ_BOUND);
        oProtInfo.add(NDXKBVProtDetail::Anfrage_Grundrabatt,
            tblKalkKopf.GrundRabatt, tblKalkKopfNew.GrundRabatt,
            num2Str(tblKalkKopf.GrundRabatt,8,2,1,0), num2Str(tblKalkKopfNew.GrundRabatt,8,2,1,0), NDXRicoKalkTblKalkKopfConstants::Grundrabatt);

        // check AbrufId
        if (!tblKalkKopf.Abruf)
        {
            tblKalkKopfNew.Abruf = nDXRicoKalkADO.getNextAbruf(bvNrRicoKalk, false);
            oProtInfo.add(NDXKBVProtDetail::Anfrage_Abruf,
            tblKalkKopf.Abruf, tblKalkKopfNew.Abruf,
                int2Str(tblKalkKopf.Abruf), int2Str(tblKalkKopfNew.Abruf), NDXRicoKalkTblKalkKopfConstants::Abruf);
        }

        // check tblKalkKopfWerte
        nDXRicoKalkADO.checkForTblKalkKopfWerteRecord(tblKalkKopfNew.AbrufID, false);

        if (oProtInfo.write(this, ado))
        {
            nDXRicoKalkADO.updateKalkKopf(tblKalkKopf.AbrufID);
        }

        //ToDo WolfA
        if(lNewAbruf && kCS_KBVRequestTable && tblKalkKopfNew.Abruf)
        {
            NDXRicoReqDocuTransfer::transferDocumentsToRicoByRequest(kCS_KBVRequestTable, tblKalkKopfNew.Abruf);
        }

        oProtInfo.parmProtID2('');
    }
}

/// <summary>
/// PaffH 23.01.24
/// </summary>
/// <param name = "_kCS_KBVRequestTable">KCS_KBVRequestTable</param>
/// <returns>container</returns>
private container getContactPersonData(KCS_KBVRequestTable _kCS_KBVRequestTable)
{
    ContactPerson   contactPerson;
    DirPartyTable dirPartyTable;
    LogisticsPostalAddress logisticsPostalAddress;
    container conDataAreaId = conNull();
    container retCon = connull();
    boolean contactFound = false;

    retCon += _kCS_KBVRequestTable.ContactPersonId != '';
    if (_kCS_KBVRequestTable.ContactPersonId)
    {
        conDataAreaId += _kCS_KBVRequestTable.DataAreaId;
        select firstonly crosscompany:conDataAreaId contactPerson
            where contactPerson.ContactPersonid ==  _kCS_KBVRequestTable.ContactPersonId
        join dirPartyTable
            where contactPerson.Party == dirPartyTable.RecId
        join logisticsPostalAddress
            where logisticsPostalAddress.Location == dirPartyTable.PrimaryAddressLocation;
        retCon += contactPerson.RecId != 0;
        if (contactPerson.RecId != 0 &&
            (logisticsPostalAddress.ZipCode != '' ||
            logisticsPostalAddress.Street != '' ||
            logisticsPostalAddress.City != ''))
        {
            retCon += logisticsPostalAddress.ZipCode;
            retCon += logisticsPostalAddress.Street;
            retCon += logisticsPostalAddress.City;
            contactFound = true;
        }
    }
    if (!contactFound)
    {
        retCon += false;
        retCon += _kCS_KBVRequestTable.AddressZipCodeId;
        retCon += _kCS_KBVRequestTable.AddressStreet;
        retCon += _kCS_KBVRequestTable.AddressCity;
    }
    return retCon;
}

/// <summary>
/// PaffH 15.01.24
/// </summary>
/// <param name = "_KCS_KBVRequestTable">KCS_KBVRequestTable</param>
/// <param name = "_displayOnConsole">boolean</param>
/// <param name = "_textToDisplayOnConsole">str</param>
/// <returns>NDXRicoKalkInteressent</returns>
protected NDXRicoKalkInteressent updateAnfrager(
    KCS_KBVRequestTable _KCS_KBVRequestTable, 
    boolean _displayOnConsole = true, 
    str _textToDisplayOnConsole = '')
{
    NDXRicoKalkInteressent nDXRicoKalkInteressent;
    changecompany(_KCS_KBVRequestTable.DataAreaId)
    {
        nDXRicoKalkInteressent = this.getContactInfo(NDXKBVAddressType::Anfrager, _KCS_KBVRequestTable.DirPartyId, 0, _KCS_KBVRequestTable.ContactPersonId);
        nDXRicoKalkInteressent = this.updateTblKalkInteressent(nDXRicoKalkInteressent, _displayOnConsole, _textToDisplayOnConsole, false);
    }
    return nDXRicoKalkInteressent;
}

/// <summary>
/// PaffH 15.01.24
/// </summary>
/// <param name = "_nDXRicoKalkInteressent">NDXRicoKalkInteressent</param>
/// <param name = "_displayOnConsole">boolean</param>
/// <param name = "_textToDisplayOnConsole">str</param>
/// <param name = "_displayOnConsoleInherit">boolean</param>
/// <param name = "_textToDisplayOnConsoleInherit">str</param>
/// <returns>NDXRicoKalkInteressent</returns>
private NDXRicoKalkInteressent updateTblKalkInteressent(
    NDXRicoKalkInteressent _nDXRicoKalkInteressent, 
    boolean _displayOnConsole = true, 
    str _textToDisplayOnConsole = '',
    boolean _displayOnConsoleInherit = true,
    str _textToDisplayOnConsoleInherit = '')
{
    TblKalkInterressent tblKalkInterressentExists = nDXRicoKalkADO.selectFromTblKalkInterressent(_nDXRicoKalkInteressent.OrgPartyId, _displayOnConsole, _textToDisplayOnConsole);
    if (!tblKalkInterressentExists.Int_id)
    {
        tblKalkInterressentExists.Int_id = 0;
        tblKalkInterressentExists.VNr = 0;
        tblKalkInterressentExists.Land_IdBound = 0;
        tblKalkInterressentExists.WKZ_BOUND = '';
        tblKalkInterressentExists.Name1 = '';
        tblKalkInterressentExists.Name2 = '';
        tblKalkInterressentExists.Name3 = '';
        tblKalkInterressentExists.Strasse = '';
        tblKalkInterressentExists.PLZ = '';
        tblKalkInterressentExists.Ort = '';
        tblKalkInterressentExists.Matchcode = '';
        tblKalkInterressentExists.OrgPartyId = '';
    }
    else
    {
        _nDXRicoKalkInteressent.ZuordnungId = tblKalkInterressentExists.ZuordnungID_Bound;
        _nDXRicoKalkInteressent.Int_ID = tblKalkInterressentExists.Int_id;
    }
    _displayOnConsole = _displayOnConsoleInherit;
    _textToDisplayOnConsole = _textToDisplayOnConsoleInherit;

    TblKalkInterressent tblKalkInterressentNew = new TblKalkInterressent();
    tblKalkInterressentNew.VNr = tblKalkInterressentExists.VNr;
    tblKalkInterressentNew.Land_IdBound = NDX_RicoKalkMapping::getMappedCountryRegionId(_nDXRicoKalkInteressent.CountryRegionId);
    tblKalkInterressentNew.MWST_IDBOUND = tblKalkInterressentExists.MWST_IDBOUND ? tblKalkInterressentExists.MWST_IDBOUND : NDXRicoKalkConstants::MWST_IDBOUND_Default;
    tblKalkInterressentNew.WKZ_BOUND = tblKalkInterressentExists.WKZ_BOUND ? tblKalkInterressentExists.WKZ_BOUND : NDXRicoKalkConstants::WKZ_BOUND_Default;
    tblKalkInterressentNew.Knr = _nDXRicoKalkInteressent.Knr_ID;
    tblKalkInterressentNew.Name1 = _nDXRicoKalkInteressent.Name;
    tblKalkInterressentNew.Name2 = _nDXRicoKalkInteressent.Name2;
    tblKalkInterressentNew.Name3 = _nDXRicoKalkInteressent.Name3;
    tblKalkInterressentNew.Strasse = _nDXRicoKalkInteressent.Street;
    tblKalkInterressentNew.PLZ = _nDXRicoKalkInteressent.ZipCode;
    tblKalkInterressentNew.Ort = _nDXRicoKalkInteressent.City;
    tblKalkInterressentNew.Matchcode = _nDXRicoKalkInteressent.NameAlias;
    tblKalkInterressentNew.OrgPartyId = _nDXRicoKalkInteressent.OrgPartyId;
    tblKalkInterressentNew.Int_id = _nDXRicoKalkInteressent.Int_ID;

    if (!tblKalkInterressentExists.Int_id)
    {
        tblKalkInterressentNew.Int_id = nDXRicoKalkADO.setNextInt_Id(_displayOnConsole, _textToDisplayOnConsole);
        tblKalkInterressentNew.ZuordnungID_Bound = NDXRicoKalkConstants::ZuordnungID_BoundNeukunde;

        nDXRicoKalkADO.insertKalkInterressent(tblKalkInterressentNew, _displayOnConsole, _textToDisplayOnConsole);

        _nDXRicoKalkInteressent.ZuordnungId = NDXRicoKalkConstants::ZuordnungID_BoundNeukunde;
    }
    else
    {
        _nDXRicoKalkInteressent.ZuordnungId = tblKalkInterressentNew.ZuordnungID_Bound;
    }
    _nDXRicoKalkInteressent.Int_ID = tblKalkInterressentNew.Int_id;

    // check contact person
    if (_nDXRicoKalkInteressent.ContactPersonId || _nDXRicoKalkInteressent.PersPartyId)
    {
        _nDXRicoKalkInteressent.Ansp_ID = this.updatetblKalkAnsprechpartner(_nDXRicoKalkInteressent, _displayOnConsole, _textToDisplayOnConsole);
    }

    // actualize Inquirer information
    oProtInfo.add(this.getProtDetailFromAddressType(_nDXRicoKalkInteressent.KBVAddressType, NDXKBVProtDetail::Anfrager_Name1),
        tblKalkInterressentExists.Name1, tblKalkInterressentNew.Name1,
        tblKalkInterressentExists.Name1, tblKalkInterressentNew.Name1, NDXRicoKalkTblKalkInterressentConstants::Name1, true);

    oProtInfo.add(this.getProtDetailFromAddressType(_nDXRicoKalkInteressent.KBVAddressType, NDXKBVProtDetail::Anfrager_Name2),
        tblKalkInterressentExists.Name2, tblKalkInterressentNew.Name2,
        tblKalkInterressentExists.Name2, tblKalkInterressentNew.Name2, NDXRicoKalkTblKalkInterressentConstants::Name2);

    oProtInfo.add(this.getProtDetailFromAddressType(_nDXRicoKalkInteressent.KBVAddressType, NDXKBVProtDetail::Anfrager_Name3),
        tblKalkInterressentExists.Name3, tblKalkInterressentNew.Name3,
        tblKalkInterressentExists.Name3, tblKalkInterressentNew.Name3, NDXRicoKalkTblKalkInterressentConstants::Name3);

    oProtInfo.add(this.getProtDetailFromAddressType(_nDXRicoKalkInteressent.KBVAddressType, NDXKBVProtDetail::Anfrager_Strasse),
        tblKalkInterressentExists.Strasse, tblKalkInterressentNew.Strasse,
        tblKalkInterressentExists.Strasse, tblKalkInterressentNew.Strasse, NDXRicoKalkTblKalkInterressentConstants::Strasse);

    oProtInfo.add(this.getProtDetailFromAddressType(_nDXRicoKalkInteressent.KBVAddressType, NDXKBVProtDetail::Anfrager_PLZ),
        tblKalkInterressentExists.PLZ, tblKalkInterressentNew.PLZ,
        tblKalkInterressentExists.PLZ, tblKalkInterressentNew.PLZ, NDXRicoKalkTblKalkInterressentConstants::PLZ);

    oProtInfo.add(this.getProtDetailFromAddressType(_nDXRicoKalkInteressent.KBVAddressType, NDXKBVProtDetail::Anfrager_Ort),
        tblKalkInterressentExists.Ort, tblKalkInterressentNew.Ort,
        tblKalkInterressentExists.Ort, tblKalkInterressentNew.Ort, NDXRicoKalkTblKalkInterressentConstants::Ort);

    oProtInfo.add(this.getProtDetailFromAddressType(_nDXRicoKalkInteressent.KBVAddressType, NDXKBVProtDetail::Anfrager_Matchcode),
        tblKalkInterressentExists.Matchcode, tblKalkInterressentNew.Matchcode,
        tblKalkInterressentExists.Matchcode, tblKalkInterressentNew.Matchcode, NDXRicoKalkTblKalkInterressentConstants::Matchcode);

    oProtInfo.add(this.getProtDetailFromAddressType(_nDXRicoKalkInteressent.KBVAddressType, NDXKBVProtDetail::Anfrager_Id),
        tblKalkInterressentExists.Int_id, tblKalkInterressentNew.Int_id,
        int2Str(tblKalkInterressentExists.Int_id), int2Str(tblKalkInterressentNew.Int_id), NDXRicoKalkTblKalkInterressentConstants::Int_id);

    oProtInfo.add(this.getProtDetailFromAddressType(_nDXRicoKalkInteressent.KBVAddressType, NDXKBVProtDetail::Anfrager_Knr),
        tblKalkInterressentExists.Knr, tblKalkInterressentNew.Knr,
        int2Str(tblKalkInterressentExists.Knr), int2Str(tblKalkInterressentNew.Knr), NDXRicoKalkTblKalkInterressentConstants::Knr);

    oProtInfo.add(this.getProtDetailFromAddressType(_nDXRicoKalkInteressent.KBVAddressType, NDXKBVProtDetail::Anfrager_Vnr),
        tblKalkInterressentExists.VNr, tblKalkInterressentNew.VNr,
        int2Str(tblKalkInterressentExists.VNr), int2Str(tblKalkInterressentNew.VNr), NDXRicoKalkTblKalkInterressentConstants::Vnr);

    oProtInfo.add(this.getProtDetailFromAddressType(_nDXRicoKalkInteressent.KBVAddressType, NDXKBVProtDetail::Anfrager_Land),
        tblKalkInterressentExists.Land_IdBound, tblKalkInterressentNew.Land_IdBound,
        int2Str(tblKalkInterressentExists.Land_IdBound), int2Str(tblKalkInterressentNew.Land_IdBound), NDXRicoKalkTblKalkInterressentConstants::Land_IdBound);

    oProtInfo.add(this.getProtDetailFromAddressType(_nDXRicoKalkInteressent.KBVAddressType, NDXKBVProtDetail::Anfrager_MwStKennung),
        tblKalkInterressentExists.MWST_IDBOUND, tblKalkInterressentNew.MWST_IDBOUND,
        int2Str(tblKalkInterressentExists.MWST_IDBOUND), int2Str(tblKalkInterressentNew.MWST_IDBOUND), NDXRicoKalkTblKalkInterressentConstants::MWST_IDBOUND);

    oProtInfo.add(this.getProtDetailFromAddressType(_nDXRicoKalkInteressent.KBVAddressType, NDXKBVProtDetail::Anfrager_WKZ),
        tblKalkInterressentExists.WKZ_BOUND, tblKalkInterressentNew.WKZ_BOUND,
        tblKalkInterressentExists.WKZ_BOUND, tblKalkInterressentNew.WKZ_BOUND, NDXRicoKalkTblKalkInterressentConstants::WKZ_BOUND);

    if (oProtInfo.write(this, ado))
    {
        nDXRicoKalkADO.updateKalkInterressent(_nDXRicoKalkInteressent.Int_ID, false);
    }
    return _nDXRicoKalkInteressent;
}

/// <summary>
/// PaffH 22.01.24
/// </summary>
/// <param name = "_nDXKBVAddressType">NDXKBVAddressType</param>
/// <param name = "_protDetailInquirer">NDXKBVProtDetail</param>
/// <returns>NDXKBVProtDetail</returns>
private NDXKBVProtDetail getProtDetailFromAddressType(NDXKBVAddressType _nDXKBVAddressType, NDXKBVProtDetail _protDetailInquirer)
{
    NDXKBVProtDetail nDXKBVProtDetail = NDXKBVProtDetail::ohneFestlegung;
    switch (_nDXKBVAddressType)
    {
        case NDXKBVAddressType::Anfrager :
            return _protDetailInquirer;
        case NDXKBVAddressType::Planer :
            switch (_protDetailInquirer)
            {
                case NDXKBVProtDetail::Anfrager_Name1 :
                    return NDXKBVProtDetail::Planer_Name1;
                case NDXKBVProtDetail::Anfrager_Name2 :
                    return NDXKBVProtDetail::Planer_Name2;
                case NDXKBVProtDetail::Anfrager_Name3 :
                    return NDXKBVProtDetail::Planer_Name3;
                case NDXKBVProtDetail::Anfrager_Strasse :
                    return NDXKBVProtDetail::Planer_Strasse;
                case NDXKBVProtDetail::Anfrager_PLZ :
                    return NDXKBVProtDetail::Planer_PLZ;
                case NDXKBVProtDetail::Anfrager_Ort :
                    return NDXKBVProtDetail::Planer_Ort;
                case NDXKBVProtDetail::Anfrager_Matchcode :
                    return NDXKBVProtDetail::Planer_Matchcode;
                case NDXKBVProtDetail::Anfrager_Id :
                    return NDXKBVProtDetail::Planer_Id;
                case NDXKBVProtDetail::Anfrager_Knr :
                    return NDXKBVProtDetail::Planer_Knr;
                case NDXKBVProtDetail::Anfrager_Vnr :
                    return NDXKBVProtDetail::Planer_Vnr;
                case NDXKBVProtDetail::Anfrager_Land :
                    return NDXKBVProtDetail::Planer_Land;
                case NDXKBVProtDetail::Anfrager_MwStKennung :
                    return NDXKBVProtDetail::Planer_MwStKennung;
                case NDXKBVProtDetail::Anfrager_WKZ :
                    return NDXKBVProtDetail::Planer_WKZ;
                default :
                    Error(strFmt("@NDXBase:NDXTheElementIsNotTakenIntoAccount", _protDetailInquirer));
            }
            break;
    }
    return nDXKBVProtDetail;
}

/// <summary>
/// PaffH 18.01.24
/// compare contact person with RicoKalk
/// </summary>
/// <param name = "_nDXRicoKalkInteressent">NDXRicoKalkInteressent</param>
/// <param name = "_displayOnConsole">boolean</param>
/// <param name = "_textToDisplayOnConsole">str</param>
/// <returns>Anspr_Id</returns>
protected int updatetblKalkAnsprechpartner(NDXRicoKalkInteressent _nDXRicoKalkInteressent, boolean _displayOnConsole = true, str _textToDisplayOnConsole = '')
{
    TblKalkAnsprechpartner tblKalkAnsprechpartner = nDXRicoKalkADO.selectFromTblKalkAnsprechpartner(_nDXRicoKalkInteressent, _displayOnConsole, _textToDisplayOnConsole);
    if (!tblKalkAnsprechpartner.Ansp_ID)
    {
        tblKalkAnsprechpartner.Anrede_BOUND = NDX_RicoKalkMapping::getMappedTitle(_nDXRicoKalkInteressent.SocialTitle);
        tblKalkAnsprechpartner.Nachname = _nDXRicoKalkInteressent.LastName;
        tblKalkAnsprechpartner.Vorname = _nDXRicoKalkInteressent.FirstName;
        tblKalkAnsprechpartner.ID_Bound = _nDXRicoKalkInteressent.Int_ID;
        tblKalkAnsprechpartner.Telefon = _nDXRicoKalkInteressent.Phone;
        tblKalkAnsprechpartner.Fax = _nDXRicoKalkInteressent.TeleFax;
        tblKalkAnsprechpartner.EMail = _nDXRicoKalkInteressent.Email;
        tblKalkAnsprechpartner.PersPartyID = _nDXRicoKalkInteressent.PersPartyId;
        tblKalkAnsprechpartner.ContactPersonID = _nDXRicoKalkInteressent.ContactPersonId;
        tblKalkAnsprechpartner = nDXRicoKalkADO.InsertKalkAnsprechpartner(tblKalkAnsprechpartner, true, _displayOnConsole, _textToDisplayOnConsole);
    }

    return tblKalkAnsprechpartner.Ansp_ID;
}

/// <summary>
/// PaffH 15.01.24
/// </summary>
/// <param name = "_addressType">NDXKBVAddressType</param>
/// <param name = "_dirPartyTableAddress">RefRecId</param>
/// <param name = "_dirPartyTableContact">RefRecId</param>
/// <param name = "_contactPersonId">ContactPersonId</param>
/// <returns>NDXRicoKalkInteressent</returns>
protected NDXRicoKalkInteressent getContactInfo(NDXKBVAddressType _addressType,
    RefRecId _dirPartyTableAddress,
    RefRecId _dirPartyTableContact,
    ContactPersonId _contactPersonId)
{
    NDXRicoKalkInteressent nDXRicoKalkInteressent;
    ContactPerson contactPerson;
    LogisticsElectronicAddress logisticsElectronicAddress;
    DirPartyTable dirPartyTableOrg;
    LogisticsPostalAddress locationOrg;
    DirPerson dirPerson;

    if (_dirPartyTableAddress)
    {
        dirPartyTableOrg = DirPartyTable::findRec(_dirPartyTableAddress);
    }
    nDXRicoKalkInteressent.OrgPartyId = dirPartyTableOrg.PartyNumber;
    nDXRicoKalkInteressent.KBVAddressType = _addressType;

    if (_addressType == NDXKBVAddressType::Anfrager)
    {
        // try to get contact info from contact person
        if (_contactPersonId)
        {
            contactPerson = ContactPerson::find(_contactPersonId);
            if (contactPerson)
            {
                dirPartyTableOrg = DirPartyTable::findRec(contactPerson.ContactForParty);
                dirPerson = DirPerson::find(contactPerson.Party);
                nDXRicoKalkInteressent.ContactPersonId = contactPerson.ContactPersonId;
                nDXRicoKalkInteressent.ContactPersonName = dirPerson.Name;
                nDXRicoKalkInteressent.FirstName = dirPerson.PhoneticFirstName;
                nDXRicoKalkInteressent.LastName = dirPerson.PhoneticLastName;
                nDXRicoKalkInteressent.SocialTitle = contactPerson.Title;
                if (dirPerson.PrimaryContactEmail)
                {
                    logisticsElectronicAddress = LogisticsElectronicAddress::findRecId(dirPerson.PrimaryContactEmail);
                    nDXRicoKalkInteressent.Email = logisticsElectronicAddress.Locator;
                }
                if (dirPerson.PrimaryContactPhone)
                {
                    logisticsElectronicAddress = LogisticsElectronicAddress::findRecId(dirPerson.PrimaryContactPhone);
                    nDXRicoKalkInteressent.Phone = logisticsElectronicAddress.Locator;
                }
                if (dirPerson.PrimaryContactTelex)
                {
                    logisticsElectronicAddress = LogisticsElectronicAddress::findRecId(dirPerson.PrimaryContactTelex);
                    nDXRicoKalkInteressent.TeleFax = logisticsElectronicAddress.Locator;
                }
                nDXRicoKalkInteressent.PersPartyId = dirPerson.PartyNumber;
                nDXRicoKalkInteressent.OrgPartyId = dirPartyTableOrg.PartyNumber;
            }
        }
    }

    if (!nDXRicoKalkInteressent.PersPartyId && _dirPartyTableContact)
    {
        dirPerson = DirPerson::find(_dirPartyTableContact);
        locationOrg = LogisticsPostalAddress::findByLocation(dirPerson.PrimaryAddressLocation);
        nDXRicoKalkInteressent.ContactPersonName = dirPerson.Name;
        nDXRicoKalkInteressent.FirstName = dirPerson.PhoneticFirstName;
        nDXRicoKalkInteressent.LastName = dirPerson.PhoneticLastName;
        nDXRicoKalkInteressent.PersPartyId = dirPerson.PartyNumber;
        nDXRicoKalkInteressent.CountryRegionId = locationOrg.CountryRegionId;
    }

    if (nDXRicoKalkInteressent.OrgPartyId)
    {
        locationOrg = LogisticsPostalAddress::findByLocation(dirPartyTableOrg.PrimaryAddressLocation);
        nDXRicoKalkInteressent.NameAlias = dirPartyTableOrg.NameAlias;
        nDXRicoKalkInteressent.Name = locationOrg.NDXLogisticsLocationName1;
        nDXRicoKalkInteressent.Name2 = locationOrg.NDXLogisticsLocationName2;
        nDXRicoKalkInteressent.Name3 = locationOrg.NDXLogisticsLocationName3;
        nDXRicoKalkInteressent.Street = locationOrg.Street;
        nDXRicoKalkInteressent.ZipCode = locationOrg.ZipCode;
        nDXRicoKalkInteressent.City = locationOrg.City;
        nDXRicoKalkInteressent.CountryRegionId = locationOrg.CountryRegionId;

        CustTable custTable = CustTable::findByPartyRecId(dirPartyTableOrg.RecId);
        if (custTable)
        {
            nDXRicoKalkInteressent.Knr_ID = str2Int(custTable.AccountNum);
        }
    }
    return nDXRicoKalkInteressent;
}

