/// <summary>
/// PaffH 27.12.23
/// </summary>
/// <param name = "_KBV_BuildingProjectTable">KCS_KBVBuildingProjectTable</param>
/// <returns>boolean</returns>
protected boolean publicate2RicoKalkLocal(KCS_KBVBuildingProjectTable  _KBV_BuildingProjectTable)
{
    this.parmStartPublicateSeconds();
    boolean lOK = false;
    if (this.parmLInfoRicoKalkSync())
    {
        Info(strFmt("@NDXRicoBV:NDXNotifikationBVToRicoKalk", NDXHelperCommon::seconds2Str(), "@NDXBase:NDXStart", _KBV_BuildingProjectTable.KCS_KBVBuildingProjectID));
    }

    try
    {
        kBV_BuildingProjectTable = _KBV_BuildingProjectTable;
        nDX_KBV2RicoKalkMap = NDX_KBV2RicoKalkMap::find(kBV_BuildingProjectTable.KCS_KBVBuildingProjectID);
        boolean lNewPublicate = (nDX_KBV2RicoKalkMap == null || nDX_KBV2RicoKalkMap.RicoKalkBVNr == 0);
        if (lNewPublicate)
        {
            this.newMapRecord();
        }
        nrIstAnfrage = nDX_KBV2RicoKalkMap.RicoKalkBVNr;

        ttsbegin;
        // generate log entry
        this.newProtRecord();
        nDX_KBV2RicoProtTable.NewPublicate = lNewPublicate ? NDXKBV2RicoProtStatus::New : NDXKBV2RicoProtStatus::Unchanged;

        oErrorMail.initialize(nDX_KBV2RicoProtTable);

        // Comparison of building project information with RicoKalk
        this.updateKalkBVKopf();

        this.updateRequests();

        this.updatePlaner();

        if (nDX_KBV2RicoProtTable.validateWrite())
        {
            nDX_KBV2RicoProtTable.updateFromNDXADO(nDXRicoKalkADO);
            nDX_KBV2RicoProtTable.write();
        }
        ttscommit;

        lOK = true;
    }
    catch
    {
        Error(strFmt("@NDXRicoBV:NDXDataTransfertoRicoKalkNotSuccessful", kBV_BuildingProjectTable.KCS_KBVBuildingProjectID));
    }

    if (this.parmLInfoRicoKalkSync())
    {
        TimeOfDay start = this.parmStartPublicateSeconds();
        TimeOfDay end = NDXHelperCommon::timeNow();
        Info(strFmt("@NDXBase:NDXSelectStatementsInsertUpdate",
            nDXRicoKalkADO.parmSelectOperations(),
            nDXRicoKalkADO.parmInsertOperations(),
            nDXRicoKalkADO.parmUpdateOperations()));
        Info(strFmt("@NDXRicoBV:NDXNotifikationBVToRicoKalkDuration", NDXHelperCommon::seconds2Str(), "@NDXBase:NDXEnd", _KBV_BuildingProjectTable.KCS_KBVBuildingProjectID, end - start));
    }
    return lOK;

}

/// <summary>
/// PaffH 25.01.24
/// </summary>
/// <returns>NDXRicoKalkInteressent</returns>
private NDXRicoKalkInteressent updatePlaner()
{
    NDXProtID2 protId2 = oProtInfo.parmProtID2();
    oProtInfo.parmProtID2(NDXRicoKalkConstants::RequestId);
    NDXRicoKalkInteressent nDXRicoKalkInteressent;
    KCS_KBVRelationsToBV kCS_KBVRelationsToBV = this.existsPlaner(nDX_KBV2RicoKalkMap.KBVBuildingProjectID);
    if (!kCS_KBVRelationsToBV)
    {
        if (this.parmLInfoRicoKalkSync())
        {
            Info(strFmt("@NDXRicoBV:NDXBuildingProjectWithoutPlaner", NDXHelperCommon::seconds2Str(), nDX_KBV2RicoKalkMap.KBVBuildingProjectID));
        }
    }
    else
    {
        nDXRicoKalkInteressent = this.getContactInfo(NDXKBVAddressType::Planer, 
            kCS_KBVRelationsToBV.DirPartyId, 0,
            kCS_KBVRelationsToBV.ContactPersonId);
        nDXRicoKalkInteressent = this.updateTblKalkInteressent(
            nDXRicoKalkInteressent,
            false,
            strFmt("@NDXRicoBV:NDXPlanerToBV", nDX_KBV2RicoKalkMap.KBVBuildingProjectID, nDX_KBV2RicoKalkMap.RicoKalkBVNr, kCS_KBVRelationsToBV.dirPartyTableOrganization().NameAlias),
            false,
            '');
    }
    TblKalkBVKopf tblKalkBVKopf = nDXRicoKalkADO.selectFromTblKalkBVKopf(nDX_KBV2RicoKalkMap.RicoKalkBVNr, false);
    if (tblKalkBVKopf.Planer_IDBOUND != nDXRicoKalkInteressent.Int_ID ||
        tblKalkBVKopf.PlanerAnspr_IDBOUND != nDXRicoKalkInteressent.Ansp_ID)
    {
        oProtInfo.add(NDXKBVProtDetail::KalkBVKopf_Planer_Id,
            tblKalkBVKopf.Planer_IDBOUND, nDXRicoKalkInteressent.Int_ID,
            int2Str(tblKalkBVKopf.Planer_IDBOUND), int2Str(nDXRicoKalkInteressent.Int_ID), NDXRicoKalkTblKalkBVKopfConstants::Planer_IDBOUND, true);
        oProtInfo.add(NDXKBVProtDetail::KalkBVKopf_PlanerAnspr_Id,
            tblKalkBVKopf.PlanerAnspr_IDBOUND, nDXRicoKalkInteressent.Ansp_ID,
            int2Str(tblKalkBVKopf.PlanerAnspr_IDBOUND), int2Str(nDXRicoKalkInteressent.Ansp_ID), NDXRicoKalkTblKalkBVKopfConstants::PlanerAnspr_IDBOUND);

        if (oProtInfo.write(this, ado))
        {
            if (this.parmLInfoRicoKalkSync())
            {
                Info(strFmt("@NDXRicoBV:NDXComparePlaner", NDXHelperCommon::seconds2Str(), nDXRicoKalkInteressent.Int_ID));
            }
            nDXRicoKalkADO.updateFromKalkBVKopf(nDX_KBV2RicoKalkMap.RicoKalkBVNr, false);
        }
    }
    oProtInfo.parmProtID2(protId2);
    return nDXRicoKalkInteressent;
}

/// <summary>
/// PaffH 25.01.24
/// </summary>
/// <param name = "_kBVBuildingProjectID">KCS_KBVBuildingProjectID</param>
/// <returns>KCS_KBVRelationsToBV</returns>
private KCS_KBVRelationsToBV existsPlaner(KCS_KBVBuildingProjectID _kBVBuildingProjectID = kBV_BuildingProjectTable.KCS_KBVBuildingProjectID)
{
    KCS_KBVRelationsToBV    kCS_KBVRelationsToBV;

    // select relation with RelationID:kCS_KBVParameters.KCS_KBVRelationID1
    select firstOnly    kCS_KBVRelationsToBV
    where           kCS_KBVRelationsToBV.KCS_KBVBuildingProjectID   == _kBVBuildingProjectID &&
                    kCS_KBVRelationsToBV.KCS_KBVRelationID          == kBVRelationIdPlaner;
    return kCS_KBVRelationsToBV;
}

/// <summary>
/// PaffH 27.12.23
/// </summary>
protected void newMapRecord()
{
    //nDXRicoKalkADO.setNextBVNum();     // neue BV-Nummer in RicoKalk bestimmen

    nrIstAnfrage = nDXRicoKalkADO.setNextBVNum();
    ttsbegin;
    nDX_KBV2RicoKalkMap.selectForUpdate(true);
    nDX_KBV2RicoKalkMap.RicoKalkBVNr            = nrIstAnfrage;
    nDX_KBV2RicoKalkMap.KBVBuildingProjectID    = kBV_BuildingProjectTable.KCS_KBVBuildingProjectID;
    if (nDX_KBV2RicoKalkMap.validateWrite())
    {
        nDX_KBV2RicoKalkMap.write();
    }
    ttscommit;
}

