protected void newProtRecord(boolean lNewRecord = false)
{
    if (lNewRecord)
    {
        nDX_KBV2RicoProtTable.clear();
    }

    //TODO PaffH: numbersequence
    //nDX_KBV2RicoProtTable.KBVProtID              = this.newGetNumNDXKBVProtId();
    //nDX_KBV2RicoProtTable.KBVProtID              = NDX_KBV2RicoProtTable::getNextProtId();
