/// <summary>
/// PaffH 15.01.24
/// </summary>
/// <param name = "_FieldType">NDXKBVProtDetail</param>
/// <param name = "_ValueOld">NDXLogEntry</param>
/// <param name = "_ValueNew">NDXLogEntry</param>
public void newProtRecordLine(NDXKBVProtDetail  _FieldType, NDXLogEntry _ValueOld, NDXLogEntry _ValueNew)
{
    ;
    try
    {
        //ttsbegin;

        //nDX_KBV2RicoProtLine = NDX_KBV2RicoProtLine::find(nDX_KBV2RicoProtTable.KBVProtIDInt, oProtInfo.parmProtID2(), _FieldType, true);
        nDX_KBV2RicoProtLine.clear();
        nDX_KBV2RicoProtLine.KBVProtID          = nDX_KBV2RicoProtTable.KBVProtID;
        nDX_KBV2RicoProtLine.KBVProtIDInt       = nDX_KBV2RicoProtTable.KBVProtIDInt;
        nDX_KBV2RicoProtLine.ProtID2            = oProtInfo.parmProtID2();

        nDX_KBV2RicoProtLine.KBVProtDetail      = _FieldType;
        nDX_KBV2RicoProtLine.ValueOld           = _ValueOld;
        nDX_KBV2RicoProtLine.ValueNew           = _ValueNew;
        //nDX_KBV2RicoProtLine.write();
        nDX_KBV2RicoProtLine.insert();
        //ttscommit;
    }
    catch
    {
        throw Error(strfmt("@NDX:NDXErrorNDX_KBV2RicoProtLineInsert", nDX_KBV2RicoProtLine.KBVProtID, nDX_KBV2RicoProtLine.ProtID2));
    }
    // handelt es sich um eine Meldung, die per EMail zu versenden ist?
    switch (_FieldType)
    {
        case NDXKBVProtDetail::Angebot_ValidateWriteError:
        case NDXKBVProtDetail::Angebot_Abgleichfehler :
            oErrorMail.addSubMessage(nDX_KBV2RicoProtLine);
            break;
    }
}

/// <summary>
/// PaffH 31.01.24
/// last modified: PaffH 04.12.25
/// get all records from RicoKalk 
/// </summary>
/// <param name = "_displayOnConsole">boolean</param>
/// <param name = "_textToDisplayOnConsole">str</param>
/// <returns>Map</returns>
Map getRicoKalkProduktGruppen(boolean _displayOnConsole = true, str _textToDisplayOnConsole = '')
{
    Map prodGrpMap = new Map(Types::Integer, Types::String);
    IEnumerator enumeratorList = nDXRicoKalkADO.selectTblProduktgruppe(_displayOnConsole, _textToDisplayOnConsole);
    if (enumeratorList != null)
    {
        while (enumeratorList.MoveNext())
        {
            TblProduktGruppe tblProduktGruppe = enumeratorList.Current;
            prodGrpMap.insert(tblProduktGruppe.ID, tblProduktGruppe.Produktgruppe);
        }
    }
    return prodGrpMap;
}

