/// <summary>
/// PaffH 01.02.24
/// AX2009: classes.NDX_KBVBuildingProject2RicoKalk.recordAvailableInRicoKalk()
/// </summary>
/// <param name = "_ndx_KBV2RicoKalkQuotation">NDX_KBV2RicoKalkQuotation</param>
/// <param name = "_displayOnConsole">boolean</param>
/// <param name = "_textToDisplayOnConsole">str</param>
/// <returns>boolean</returns>
private boolean recordAvailableInRicoKalk(NDX_KBV2RicoKalkQuotation _ndx_KBV2RicoKalkQuotation, boolean _displayOnConsole = true, str _textToDisplayOnConsole = '')
{
    boolean     recordAvailableInRico = true;
    NDX_KBV2RicoKalkMap lNDX_KBV2RicoKalkMap;

    if(_ndx_KBV2RicoKalkQuotation)
    {
        //Get Rico BV project id
        lNDX_KBV2RicoKalkMap = NDX_KBV2RicoKalkMap::find(_ndx_KBV2RicoKalkQuotation.KBVBuildingProjectID);

        if(lNDX_KBV2RicoKalkMap)
        {
            TblKalkKopf tblKalkKopf = nDXRicoKalkADO.selectTblKalkKopfForAvailableCheck(lNDX_KBV2RicoKalkMap, _ndx_KBV2RicoKalkQuotation, _displayOnConsole, _textToDisplayOnConsole);
            recordAvailableInRico = (tblKalkKopf.AbrufID == 0);
        }
    }
    return recordAvailableInRico;
}

/// <summary>
/// PaffH 29.01.24
/// AX2009: classes.NDX_KBVBuildingProject2RicoKalk.transRicoKalkAng2KBV()
/// transfer RicoKalk quotations to D365FO
/// </summary>
/// <param name = "_contract">NDXRicoKalk2KBVBuildingProjectContract</param>
/// <returns>container</returns>
public container transRicoKalkAng2KBV(NDXRicoKalk2KBVBuildingProjectContract _contract)
{
    System.Exception ex;
    boolean withThrowError = false;
    NDX_KBV2RicoKalkQuotation kBV2RicoKalkQuotation, kBV2RicoKalkQuotationOld, kBV2RicoKalkQuotationDeleted;
    boolean lBVRicoExists;
    boolean lNewAngebot, lNew;
    NDXRicoBVBezeichnung ricoBVBez1, ricoBVBez2;
    Set receivedRicoRecords;
    boolean doesExistAtRico;
    int anzBV = 0;
    int anzBVRico = 0;
    int anzQuotation = 0;
    int nAnzProtPos;
    KCS_StatusId kCS_StatusIdNew;
    Info(strFmt("@NDXRicoBV:NDXQuotationComparison", NDXHelperCommon::seconds2Str(), "@NDXBase:NDXStart"));
    try
    {
        Map prodGrpMap = this.getRicoKalkProduktGruppen(false, "@NDXRicoBV:NDXRicoKalkQuotationComparison");

        changecompany(conPeek(conRicoUK, 1))
        {
            Query q = new Query();
            QueryBuildDataSource qbdsKBV2RicoKalkMap = q.addDataSource(tableNum(NDX_KBV2RicoKalkMap));
            qbdsKBV2RicoKalkMap.addRange(fieldNum(NDX_KBV2RicoKalkMap, RicoKalkBVNr)).value(SysQuery::valueNot(0));
            if ((_contract.parmKBVBuildingProjectIdFrom() && _contract.parmKBVBuildingProjectIdTo()) ||
            (_contract.parmFromDate() && _contract.parmToDate()) ||
            (_contract.parmCheckDays()))
            {
                QueryBuildDataSource qbdsKBVBuildingProjectTable = qbdsKBV2RicoKalkMap.addDataSource(tableNum(KCS_KBVBuildingProjectTable));
                qbdsKBVBuildingProjectTable.relations(true);
                if (_contract.parmKBVBuildingProjectIdFrom() && _contract.parmKBVBuildingProjectIdTo())
                {
                    qbdsKBVBuildingProjectTable
                    .addRange(fieldNum(KCS_KBVBuildingProjectTable, KCS_KBVBuildingProjectID))
                    .value(SysQuery::range(_contract.parmKBVBuildingProjectIdFrom(), _contract.parmKBVBuildingProjectIdTo()));
                }
                else if (_contract.parmFromDate() && _contract.parmToDate())
                {
                    qbdsKBVBuildingProjectTable
                    .addRange(fieldNum(KCS_KBVBuildingProjectTable, KCS_KBVReceiptDate))
                    .value(SysQuery::range(_contract.parmFromDate(), _contract.parmToDate()));
                }
                else if (_contract.parmCheckDays())
                {
                    qbdsKBVBuildingProjectTable
                    .addRange(fieldNum(KCS_KBVBuildingProjectTable, KCS_KBVReceiptDate))
                        .value(SysQuery::range((NDXHelperCommon::SystemDateGet() - _contract.parmCheckDays()), NDXHelperCommon::SystemDateGet()));
                }
            }
            else if (_contract.parmKBVBuildingProjectID())
            {
                qbdsKBV2RicoKalkMap.addRange(fieldNum(NDX_KBV2RicoKalkMap, KBVBuildingProjectID)).value(queryValue(_contract.parmKBVBuildingProjectID()));
            }
            QueryRun qr = new QueryRun(q);
            while (qr.next())
            {
                ++anzBV;
                receivedRicoRecords = new Set(Types::Integer);
                NDX_KBV2RicoKalkMap nDX_KBV2RicoKalkMapLoc = qr.get(tableNum(NDX_KBV2RicoKalkMap));
                kBV2RicoKalkQuotationDeleted.clear();

                delete_from kBV2RicoKalkQuotationOld
                where   kBV2RicoKalkQuotationOld.KBVBuildingProjectID == nDX_KBV2RicoKalkMapLoc.KBVBuildingProjectID &&
                        kBV2RicoKalkQuotationOld.OldValue             == NoYes::Yes;

                // nothing to do, if BV doesn't exists
                if (!KCS_KBVBuildingProjectTable::find(nDX_KBV2RicoKalkMapLoc.KBVBuildingProjectID))
                {
                    continue;
                }

                [lBVRicoExists, ricoBVBez1, ricoBVBez2] = this.existsRicoKalkBV(
                    nDX_KBV2RicoKalkMapLoc.RicoKalkBVNr,
                    false,
                    strFmt("@NDXRicoBV:NDXRicoKalkQuotationTransfer", nDX_KBV2RicoKalkMapLoc.RicoKalkBVNr, nDX_KBV2RicoKalkMapLoc.KBVBuildingProjectID)
                    );
                info(strFmt("@NDXRicoBV:NDXRicoKalkQuotationTransfer", nDX_KBV2RicoKalkMapLoc.RicoKalkBVNr, nDX_KBV2RicoKalkMapLoc.KBVBuildingProjectID));

                try
                {
                    ttsbegin;
                    str whereAdd = strFmt(NDXSqlConstants::SQLAndFieldGreaterInt, NDXRicoKalkTblKalkKopfConstants::Abruf, 0);
                    whereAdd += strFmt(NDXSqlConstants::SQLAndFieldNotIn, NDXRicoKalkTblKalkKopfConstants::Verfolg_Status, '50,51,52');

                    IEnumerator enumeratorList = nDXRicoKalkADO.selectTblKalkKopf(nDX_KBV2RicoKalkMapLoc.RicoKalkBVNr, whereAdd, false);
                    while (enumeratorList.MoveNext())
                    {
                        TblKalkKopf tblKalkKopf = enumeratorList.Current;

                        kBV2RicoKalkQuotation   = NDX_KBV2RicoKalkQuotation::findAbrufID(tblKalkKopf.AbrufID, NoYes::No, true);

                        receivedRicoRecords.add(tblKalkKopf.Abruf);

                        //If there is a record in AX that does not exist on RicoKalk we delete the record
                        kBV2RicoKalkQuotationDeleted = NDX_KBV2RicoKalkQuotation::findPossibleDeletedRecord(kBV2RicoKalkQuotation, true);
                        if(kBV2RicoKalkQuotationDeleted)
                        {
                            kBV2RicoKalkQuotationDeleted.delete();
                        }
                        lNew = (kBV2RicoKalkQuotation == null);

                        // save old/existing values from RicoKalk
                        kBV2RicoKalkQuotationOld = kBV2RicoKalkQuotation.data();
                        kBV2RicoKalkQuotationOld.OldValue = NoYes::Yes;
                        kBV2RicoKalkQuotationOld.RecId = 0;

                        kBV2RicoKalkQuotation.AbrufID = tblKalkKopf.AbrufID;
                        kBV2RicoKalkQuotation.Abruf = tblKalkKopf.Abruf;
                        kBV2RicoKalkQuotation.IntID = tblKalkKopf.Int_IDBOUND;
                        kBV2RicoKalkQuotation.Int_Name = tblKalkKopf.Name1;
                        kBV2RicoKalkQuotation.KBVBuildingProjectID = nDX_KBV2RicoKalkMapLoc.KBVBuildingProjectID;

                        kBV2RicoKalkQuotation.KBVRequestID = tblKalkKopf.KBVRequestID ? tblKalkKopf.KBVRequestID : "@NDX:NDXMissingKBVRequestId";
                        kBV2RicoKalkQuotation.QuotationId = strfmt(NDXRicoKalkConstants::QuotationIdPattern, 
                            NDXRicoKalkConstants::QuotationIdPrefix, 
                            nDX_KBV2RicoKalkMapLoc.RicoKalkBVNr,
                            tblKalkKopf.Abruf);
                        if (prodGrpMap.exists(tblKalkKopf.Produktgruppe_IDBound))
                        {
                            kBV2RicoKalkQuotation.KBVProductGroupID = prodGrpMap.lookup(tblKalkKopf.Produktgruppe_IDBound);
                        }
                        kBV2RicoKalkQuotation.Datum_Angelegt = tblKalkKopf.Datum_Auftrag;
                        kBV2RicoKalkQuotation.QuotationExpiryDate = tblKalkKopf.Datum_Sollabgabe;
                        kBV2RicoKalkQuotation.VerfolgStatus = tblKalkKopf.Verfolg_Status;
                        kBV2RicoKalkQuotation.KCS_KBVSubject = strfmt(NDXPlaceholderConstants::FirstSpaceSecond, ricoBVBez1, ricoBVBez2);
                        kBV2RicoKalkQuotation.QuotationTakerId = tblKalkKopf.Kalkulator_IDBound;
                        kBV2RicoKalkQuotation.Verfolg_AenderDatum = tblKalkKopf.Verfolg_AenderDatum;
                        //try
                        //{
                        if (kBV2RicoKalkQuotation.validateWrite())
                        {
                            kBV2RicoKalkQuotation.write();
                        }

                        if (!lNew && kBV2RicoKalkQuotationOld.validateWrite())
                        {
                            NDX_KBV2RicoKalkQuotation kBV2RicoKalkQuotationOld2 = NDX_KBV2RicoKalkQuotation::findAbrufID(kBV2RicoKalkQuotationOld.AbrufId, kBV2RicoKalkQuotationOld.OldValue, true);
                            if (kBV2RicoKalkQuotationOld2)
                            {
                                buf2Buf(kBV2RicoKalkQuotationOld, kBV2RicoKalkQuotationOld2);
                                select forupdate firstonly kBV2RicoKalkQuotationOld where kBV2RicoKalkQuotationOld.RecId == kBV2RicoKalkQuotationOld2.RecId;
                                buf2Buf(kBV2RicoKalkQuotationOld2, kBV2RicoKalkQuotationOld);
                            }
                            kBV2RicoKalkQuotationOld.write();
                        }
                        //}
                        //catch
                        //{
                        //    error(strFmt("@NDXBase:NDXSavingError", 'kBV2RicoKalkQuotation'));
                        //}
                    }
                    ttscommit;

                    // generate new log header
                    ttsbegin;
                    nanzProtPos = 0;
                    this.newProtRecord();
                    nDX_KBV2RicoProtTable.KBVBuildingProjectID = nDX_KBV2RicoKalkMapLoc.KBVBuildingProjectID;
                    nDX_KBV2RicoProtTable.RicoKalkBVNr = nDX_KBV2RicoKalkMapLoc.RicoKalkBVNr;
                    nDX_KBV2RicoProtTable.ProtKopfTyp = NDXProtKopfTyp::RicoKalk_Angebot_Abgleich;
                    oErrorMail.initialize(nDX_KBV2RicoProtTable);

                    // Werte je Abruf ermitteln (KalkKopfWerte)
                    Query qRicoKalkQuotation = new Query();
                    QueryBuildDataSource qbdsRicoKalkQuotation = qRicoKalkQuotation.addDataSource(tableNum(NDX_KBV2RicoKalkQuotation));
                    qbdsRicoKalkQuotation.addRange(fieldNum(NDX_KBV2RicoKalkQuotation, KBVBuildingProjectID)).value(queryValue(nDX_KBV2RicoKalkMapLoc.KBVBuildingProjectID));
                    qbdsRicoKalkQuotation.addRange(fieldNum(NDX_KBV2RicoKalkQuotation, OldValue)).value(queryValue(NoYes::No));

                    str qString = strFmt(NDXSqlConstants::SQLFieldNotEqualInt, fieldstr(NDX_KBV2RicoKalkQuotation, VerfolgStatus), 0);
                    qString += ' ' + strfmt(NDXSqlConstants::SQLAndFieldNotEqualInt, fieldstr(NDX_KBV2RicoKalkQuotation, VerfolgStatus), 50);
                    qString += ' ' + strfmt(NDXSqlConstants::SQLAndFieldNotEqualInt, fieldstr(NDX_KBV2RicoKalkQuotation, VerfolgStatus), 51);
                    qString += ' ' + strfmt(NDXSqlConstants::SQLAndFieldNotEqualInt, fieldstr(NDX_KBV2RicoKalkQuotation, VerfolgStatus), 52);
                    qbdsRicoKalkQuotation.addRange(fieldNum(NDX_KBV2RicoKalkQuotation, VerfolgStatus)).value(qString);
                    qbdsRicoKalkQuotation.update(true);
                    QueryRun qrRicoKalkQuotation = new QueryRun(qRicoKalkQuotation);
                    while (qrRicoKalkQuotation.next())
                    {
                        kBV2RicoKalkQuotation = qrRicoKalkQuotation.get(tableNum(NDX_KBV2RicoKalkQuotation));

                        oProtInfo.parmProtID2(kBV2RicoKalkQuotation.QuotationId);
                        doesExistAtRico = receivedRicoRecords.in(kBV2RicoKalkQuotation.Abruf);
                        if(!doesExistAtRico && this.recordAvailableInRicoKalk(kBV2RicoKalkQuotation, false, ''))
                        {
                            //Find records for deletion in AX (SalesQuotation and RicoKalkQuotaion table)
                            kBV2RicoKalkQuotationOld = NDX_KBV2RicoKalkQuotation::findAbrufID(kBV2RicoKalkQuotation.AbrufID, NoYes::No,true);
                            SalesQuotationTable salesQuotationTable = SalesQuotationTable::find(kBV2RicoKalkQuotation.QuotationId, true);

                            if (salesQuotationTable)
                            {
                                // Angebotsnummer
                                // We log only the Angebot_AngebotNr for deletion
                                oProtInfo.add(NDXKBVProtDetail::Angebot_AngebotNr,
                                kBV2RicoKalkQuotationOld.QuotationId, "@NDXBase:NDXDeleted",
                                kBV2RicoKalkQuotationOld.QuotationId, "@NDXBase:NDXDeleted", '', true);
                                // Delete record in AX in SalesQuotation and RicoKalkQuotaion table
                                salesQuotationTable.delete();

                                //publicate log
                                nDX_KBV2RicoProtTable.NewPublicate = NDXKBV2RicoProtStatus::Deleted;
                                nDX_KBV2RicoProtTable.CounterDeleteStatement += 1;

                                nAnzProtPos += oProtInfo.write(this);
                            }
                            if (kBV2RicoKalkQuotationOld)
                            {
                                kBV2RicoKalkQuotationOld.delete();
                            }

                            continue;
                        }
                        TblKalkKopfWerte tblKalkKopfWerte = nDXRicoKalkADO.selectTblKalkKopfWerte(kBV2RicoKalkQuotation.AbrufId, false);
                        if (tblKalkKopfWerte.Abruf_IDBound)
                        {
                            if (!tblKalkKopfWerte.ID)
                            {
                                kBV2RicoKalkQuotation.OldValue = NoYes::Yes;
                                kBV2RicoKalkQuotation.update();
                                continue;
                            }

                            kBV2RicoKalkQuotation.KalkKopfWerteID = tblKalkKopfWerte.ID;
                            kBV2RicoKalkQuotation.VKLohnS = tblKalkKopfWerte.VKLohnS;
                            kBV2RicoKalkQuotation.VKDuebelS = tblKalkKopfWerte.VKDuebelS;
                            kBV2RicoKalkQuotation.VKMatS = tblKalkKopfWerte.VKMatS;
                            kBV2RicoKalkQuotation.VKLohnSRab = tblKalkKopfWerte.VKLohnSRab;
                            kBV2RicoKalkQuotation.VKDuebelSRab = tblKalkKopfWerte.VKDuebelSRab;
                            kBV2RicoKalkQuotation.VKMatSRab = tblKalkKopfWerte.VKMatSRab;
                            kBV2RicoKalkQuotation.QuotationAmount = kBV2RicoKalkQuotation.VKLohnSRab
                            + kBV2RicoKalkQuotation.VKDuebelSRab
                            + kBV2RicoKalkQuotation.VKMatSRab;
                        }

                        // is the interested party a busRel or customer
                        CustTable custTable;
                        smmBusRelTable smmBusRelTable;
                        SalesQuotationTable salesQuotationTable;
                        DirPartyTable dirPartyTable;

                        TblKalkInterressent tblKalkInterressent = nDXRicoKalkADO.selectTblKalkInterressentFromIntId(kBV2RicoKalkQuotation.IntId, false);
                        if (tblKalkInterressent.Int_Id)
                        {
                            kBV2RicoKalkQuotation.OrgPartyID = tblKalkInterressent.OrgPartyId;
                        }
                        if (kBV2RicoKalkQuotation.OrgPartyID)
                        {
                            dirPartyTable = DirPartyTable::findByNum(kBV2RicoKalkQuotation.OrgPartyID, false, DirPartyType::Organization);
                            if (dirPartyTable)
                            {
                                custTable = CustTable::findByPartyRecId(dirPartyTable.RecId);
                                if (custTable)
                                {
                                    kBV2RicoKalkQuotation.CustTable = custTable.RecId;
                                    kBV2RicoKalkQuotation.CustAccount = custTable.AccountNum;
                                }
                                else
                                {
                                    smmBusRelTable = smmBusRelTable::findByParty(dirPartyTable.RecId);
                                    if (smmBusRelTable)
                                    {
                                        kBV2RicoKalkQuotation.smmBusRelTable = smmBusRelTable.RecId;
                                        kBV2RicoKalkQuotation.BusRelAccount = smmBusRelTable.BusRelAccount;
                                    }
                                }
                            }
                        }
                        if (!custTable && !smmBusRelTable)
                        {
                            dirPartyTable = DirPartyTable::findByNum(NDXRicoKalkConstants::GBRicoAbgleichFehler, false, DirPartyType::Organization);
                            smmBusRelTable = smmBusRelTable::findByParty(dirPartyTable.RecId);
                            if (smmBusRelTable)
                            {
                                kBV2RicoKalkQuotation.smmBusRelTable = smmBusRelTable.RecId;
                                kBV2RicoKalkQuotation.BusRelAccount = smmBusRelTable.BusRelAccount;
                            }
                        }
                        if (!custTable && !smmBusRelTable)
                        {
                            if (kBV2RicoKalkQuotation.validateWrite())
                            {
                                kBV2RicoKalkQuotation.write();
                            }
                            else
                            {
                                // logging
                                oProtInfo.parmProtID2(kBV2RicoKalkQuotation.QuotationId);
                                oProtInfo.add(NDXKBVProtDetail::Angebot_Abgleichfehler,
                                kBV2RicoKalkQuotation.QuotationId, kBV2RicoKalkQuotation.KBVBuildingProjectID ,
                                kBV2RicoKalkQuotation.QuotationId, kBV2RicoKalkQuotation.KBVBuildingProjectID , '', true);
                                nAnzProtPos += oProtInfo.write(this);
                            }

                            // logging
                            oProtInfo.parmProtID2(kBV2RicoKalkQuotation.QuotationId);
                            oProtInfo.add(NDXKBVProtDetail::Angebot_Abgleichfehler, 
                                kBV2RicoKalkQuotation.QuotationId, kBV2RicoKalkQuotation.OrgPartyID ,
                                kBV2RicoKalkQuotation.QuotationId, kBV2RicoKalkQuotation.OrgPartyID , '', true);
                            nAnzProtPos += oProtInfo.write(this);
                        }
                        else
                        {
                            // generate salesQuotation
                            ++anzQuotation;
                            salesQuotationTable = SalesQuotationTable::find(kBV2RicoKalkQuotation.QuotationId, true);
                            lNewAngebot = (salesQuotationTable == null);
                            if (lNewAngebot)
                            {
                                salesQuotationTable.initValue();
                                if (custTable)
                                {
                                    salesQuotationTable.CustAccount = custTable.AccountNum;
                                    salesQuotationTable.initFromCustTable();
                                }
                                else if (smmBusRelTable)
                                {
                                    salesQuotationTable.BusRelAccount = smmBusRelTable.BusRelAccount;
                                    salesQuotationTable.initFromBusinessRelationTable();
                                }
                                salesQuotationTable.QuotationId = kBV2RicoKalkQuotation.QuotationId;
                                salesQuotationTable.ShippingDateRequested = NDXHelperCommon::systemDateGet();
                                nDX_KBV2RicoProtTable.NewPublicate = NDXKBV2RicoProtStatus::New;
                                nDX_KBV2RicoProtTable.CounterInsertStatement += 1;
                            }
                            else
                            {
                                if (custTable && custTable.AccountNum != salesQuotationTable.CustAccount)
                                {
                                    salesQuotationTable.CustAccount = custTable.AccountNum;
                                    salesQuotationTable.initFromCustTable();
                                }
                                if (!custTable && smmBusRelTable.BusRelAccount != salesQuotationTable.BusRelAccount)
                                {
                                    salesQuotationTable.BusRelAccount = smmBusRelTable.BusRelAccount;
                                    salesQuotationTable.initFromBusinessRelationTable();
                                }
                                // Either customer or busRel (customer priority)
                                if (salesQuotationTable.CustAccount && salesQuotationTable.BusRelAccount)
                                {
                                    salesQuotationTable.BusRelAccount = '';
                                }
                                if (custTable)
                                {
                                    salesQuotationTable.SalesUnitId = smmBusRelSalesDistrictGroup::avaFind(custTable.SalesDistrictId).KCS_KBVsmmSalesUnitId;
                                }
                                else if (smmBusRelTable)
                                {
                                    salesQuotationTable.SalesUnitId = smmBusRelSalesDistrictGroup::avaFind(smmBusRelTable.SalesDistrict).KCS_KBVsmmSalesUnitId;
                                }
                                nDX_KBV2RicoProtTable.CounterUpdateStatement += 1;
                            }
                            //AX2009:
                            // 1.14: NDX/PAFFH/NDX_TASK1235003877/19.06.2015
                            //       SalesResponsible wird auch bei einem neuen Angebot falsch mit dem MainContact initialisiert!
                            //salesQuotationTable.SalesResponsible = smmSalesUnit::NDX_getSalesUnitManager(salesQuotationTable.SalesUnitId, false);

                            if (kBV2RicoKalkQuotation.validateWrite())
                            {
                                kBV2RicoKalkQuotation.write();
                            }
                            else
                            {
                                // logging
                                oProtInfo.parmProtID2(kBV2RicoKalkQuotation.QuotationId);
                                oProtInfo.add(NDXKBVProtDetail::Angebot_Abgleichfehler,
                                kBV2RicoKalkQuotation.QuotationId, kBV2RicoKalkQuotation.KBVBuildingProjectID ,
                                kBV2RicoKalkQuotation.QuotationId, kBV2RicoKalkQuotation.KBVBuildingProjectID , '', true);
                                nAnzProtPos += oProtInfo.write(this);
                            }
                            salesQuotationTable.KCS_KBVProductGroupID = kBV2RicoKalkQuotation.KBVProductGroupID;
                            salesQuotationTable.modifiedField(fieldNum(SalesQuotationTable, KCS_KBVProductGroupID));
                            salesQuotationTable.KCS_QuotationAmount = kBV2RicoKalkQuotation.QuotationAmount;
                            salesQuotationTable.QuotationExpiryDate = kBV2RicoKalkQuotation.QuotationExpiryDate;
                            salesQuotationTable.KCS_KBVRequestId = kBV2RicoKalkQuotation.KBVRequestId;

                            if (kBV2RicoKalkQuotation.BusRelAccount == NDXRicoKalkConstants::GBRicoAbgleichFehler)
                            {
                                salesQuotationTable.QuotationName = strFmt(NDXRicoKalkConstants::GBRicoAbgleichFehlerQuotationName
                                    , kBV2RicoKalkQuotation.IntId, kBV2RicoKalkQuotation.Int_Name);
                            }
                            salesQuotationTable.KCS_KBVSubject = kBV2RicoKalkQuotation.KCS_KBVSubject;

                            // worker sales taker
                            salesQuotationTable.NDXRicoQuotationTaker = kBV2RicoKalkQuotation.QuotationTakerId;
                            NDXRICOUserMap nDXRicoUserMap = NDXRICOUserMap::findRicoUser(kBV2RicoKalkQuotation.QuotationTakerId);
                            HcmPersonnelNumberId personnelNumber = nDXRicoUserMap ? nDXRicoUserMap.HcmPersonnelNumberId : kBV2RicoKalkQuotation.QuotationTakerId;
                            HcmWorker hCMWorker = HcmWorker::findByPersonnelNumber(personnelNumber);
                            if (hCMWorker)
                            {
                                salesQuotationTable.WorkerSalesTaker = hCMWorker.RecId;
                            }
                            salesQuotationTable.KCS_DecisionDate = kBV2RicoKalkQuotation.Verfolg_AenderDatum;

                            if (salesQuotationTable.validateWrite())
                            {
                                // TODO PaffH: Prüfen, ob Maßnahme notwendig ist
                                // Workaround, damit vorgegebene Rico-Angebotsnummer nicht überschrieben wird
                                if (lNewAngebot)
                                {
                                    salesQuotationTable.KCS_KBVBuildingProjectID    = '';
                                }

                                if (salesQuotationTable.RecId)
                                {
                                    salesQuotationTable.update(true, _contract.parmCalledFromSysOperations());
                                }
                                else
                                {
                                    salesQuotationTable.insert();
                                }
                                if (lNewAngebot)
                                {
                                    salesQuotationTable.KCS_KBVBuildingProjectID    = kBV2RicoKalkQuotation.KBVBuildingProjectID;
                                    salesQuotationTable.update();
                                }

                                kCS_StatusIdNew = NDX_QuotationStatusMap2RicoKalk::getKCS_StatusId(kBV2RicoKalkQuotation.VerfolgStatus);
                                if (kCS_StatusIdNew && salesQuotationTable.KCS_StatusId != kCS_StatusIdNew)
                                {
                                    salesQuotationTable.KCS_StatusId = kCS_StatusIdNew;
                                    salesQuotationTable.QuotationStatus = KCS_QuotationStatus::find(salesQuotationTable.KCS_StatusId).KCS_SalesQuotationStatus;
                                    salesQuotationTable.update();

                                    // set status of other quotations from the building project
                                    Args args = new Args();
                                    args.record(salesQuotationTable);
                                    AVAQuotationStatusModify aVAQuotationStatusModify = AVAQuotationStatusModify::construct(args);
                                    aVAQuotationStatusModify.init();
                                    aVAQuotationStatusModify.updateSalesQuotation();
                                    salesQuotationTable.reread();
                                }
                            }
                            else
                            {
                                error(strFmt("@NDXRicoBV:NDXRicoKalkQuotationNotSaved", kBV2RicoKalkQuotation.QuotationId, kBV2RicoKalkQuotation.KBVBuildingProjectID));
                                // logging
                                oProtInfo.parmProtID2(kBV2RicoKalkQuotation.QuotationId);
                                oProtInfo.add(NDXKBVProtDetail::Angebot_ValidateWriteError,
                                kBV2RicoKalkQuotation.QuotationId, kBV2RicoKalkQuotation.KBVBuildingProjectID ,
                                kBV2RicoKalkQuotation.QuotationId, kBV2RicoKalkQuotation.KBVBuildingProjectID , '', true);
                                nAnzProtPos += oProtInfo.write(this);
                            }

                            // logging
                            kBV2RicoKalkQuotationOld = NDX_KBV2RicoKalkQuotation::findAbrufID(kBV2RicoKalkQuotation.AbrufId, NoYes::Yes);

                            oProtInfo.add(NDXKBVProtDetail::Angebot_AngebotNr,
                                kBV2RicoKalkQuotationOld.QuotationId, kBV2RicoKalkQuotation.QuotationId,
                                kBV2RicoKalkQuotationOld.QuotationId, kBV2RicoKalkQuotation.QuotationId, '', true);

                            oProtInfo.add(NDXKBVProtDetail::Angebot_Produktgruppe, 
                                kBV2RicoKalkQuotationOld.KBVProductGroupID, kBV2RicoKalkQuotation.KBVProductGroupID,
                                kBV2RicoKalkQuotationOld.KBVProductGroupID, kBV2RicoKalkQuotation.KBVProductGroupID);

                            oProtInfo.add(NDXKBVProtDetail::Angebot_AbrufID, 
                                kBV2RicoKalkQuotationOld.AbrufID, kBV2RicoKalkQuotation.AbrufID,
                                int2str(kBV2RicoKalkQuotationOld.AbrufID), int2str(kBV2RicoKalkQuotation.AbrufID));

                            oProtInfo.add(NDXKBVProtDetail::Angebot_Abruf, 
                                kBV2RicoKalkQuotationOld.Abruf, kBV2RicoKalkQuotation.Abruf,
                                int2str(kBV2RicoKalkQuotationOld.Abruf), int2str(kBV2RicoKalkQuotation.Abruf));

                            oProtInfo.add(NDXKBVProtDetail::Angebot_VKDuebel, 
                                kBV2RicoKalkQuotationOld.VKDuebelS, kBV2RicoKalkQuotation.VKDuebelS,
                                num2str(kBV2RicoKalkQuotationOld.VKDuebelS,12,2,2,1), num2str(kBV2RicoKalkQuotation.VKDuebelS,12,2,2,1));

                            oProtInfo.add(NDXKBVProtDetail::Angebot_VKLohn, 
                                kBV2RicoKalkQuotationOld.VKLohnS, kBV2RicoKalkQuotation.VKLohnS,
                                num2str(kBV2RicoKalkQuotationOld.VKLohnS,12,2,2,1), num2str(kBV2RicoKalkQuotation.VKLohnS,12,2,2,1));

                            oProtInfo.add(NDXKBVProtDetail::Angebot_VKMat, 
                                kBV2RicoKalkQuotationOld.VKMatS, kBV2RicoKalkQuotation.VKMatS,
                                num2str(kBV2RicoKalkQuotationOld.VKMatS,12,2,2,1), num2str(kBV2RicoKalkQuotation.VKMatS,12,2,2,1));

                            oProtInfo.add(NDXKBVProtDetail::Angebot_VKDuebelRab, 
                                kBV2RicoKalkQuotationOld.VKDuebelSRab, kBV2RicoKalkQuotation.VKDuebelSRab,
                                num2str(kBV2RicoKalkQuotationOld.VKDuebelSRab,12,2,2,1), num2str(kBV2RicoKalkQuotation.VKDuebelSRab,12,2,2,1));

                            oProtInfo.add(NDXKBVProtDetail::Angebot_VKLohnRab, 
                                kBV2RicoKalkQuotationOld.VKLohnSRab, kBV2RicoKalkQuotation.VKLohnSRab,
                                num2str(kBV2RicoKalkQuotationOld.VKLohnSRab,12,2,2,1), num2str(kBV2RicoKalkQuotation.VKLohnSRab,12,2,2,1));

                            oProtInfo.add(NDXKBVProtDetail::Angebot_VKMatRab, 
                                kBV2RicoKalkQuotationOld.VKMatSRab, kBV2RicoKalkQuotation.VKMatSRab,
                                num2str(kBV2RicoKalkQuotationOld.VKMatSRab,12,2,2,1), num2str(kBV2RicoKalkQuotation.VKMatSRab,12,2,2,1));

                            oProtInfo.add(NDXKBVProtDetail::Angebot_Angebotssumme, 
                                kBV2RicoKalkQuotationOld.QuotationAmount, kBV2RicoKalkQuotation.QuotationAmount,
                                num2str(kBV2RicoKalkQuotationOld.QuotationAmount,12,2,2,1)   , num2str(kBV2RicoKalkQuotation.QuotationAmount,12,2,2,1));

                            oProtInfo.add(NDXKBVProtDetail::Angebot_Kunde, 
                                kBV2RicoKalkQuotationOld.CustAccount, kBV2RicoKalkQuotation.CustAccount,
                                kBV2RicoKalkQuotationOld.CustAccount, kBV2RicoKalkQuotation.CustAccount);

                            oProtInfo.add(NDXKBVProtDetail::Angebot_GB, 
                                kBV2RicoKalkQuotationOld.BusRelAccount, kBV2RicoKalkQuotation.BusRelAccount,
                                kBV2RicoKalkQuotationOld.BusRelAccount, kBV2RicoKalkQuotation.BusRelAccount);

                            oProtInfo.add(NDXKBVProtDetail::Angebot_Ablaufdatum, 
                                kBV2RicoKalkQuotationOld.QuotationExpiryDate, kBV2RicoKalkQuotation.QuotationExpiryDate,
                                date2str(kBV2RicoKalkQuotationOld.QuotationExpiryDate, 123, DateDay::Digits2, DateSeparator::Dot, DateMonth::Digits2, DateSeparator::Dot, DateYear::Digits4),
                                date2str(kBV2RicoKalkQuotation.QuotationExpiryDate, 123, DateDay::Digits2, DateSeparator::Dot, DateMonth::Digits2, DateSeparator::Dot, DateYear::Digits4));

                            oProtInfo.add(NDXKBVProtDetail::Angebot_Erstellungsdatum, 
                                kBV2RicoKalkQuotationOld.Datum_Angelegt, kBV2RicoKalkQuotation.Datum_Angelegt,
                                date2str(DateTimeUtil::date(kBV2RicoKalkQuotationOld.Datum_Angelegt), 123, DateDay::Digits2, DateSeparator::Dot, DateMonth::Digits2, DateSeparator::Dot, DateYear::Digits4),
                                date2str(DateTimeUtil::date(kBV2RicoKalkQuotation.Datum_Angelegt), 123, DateDay::Digits2, DateSeparator::Dot, DateMonth::Digits2, DateSeparator::Dot, DateYear::Digits4));

                            oProtInfo.add(NDXKBVProtDetail::Angebot_VerfolgStatus, 
                                kBV2RicoKalkQuotationOld.VerfolgStatus, kBV2RicoKalkQuotation.VerfolgStatus,
                                int2str(kBV2RicoKalkQuotationOld.VerfolgStatus), int2str(kBV2RicoKalkQuotation.VerfolgStatus));

                            oProtInfo.add(NDXKBVProtDetail::Angebot_Bearbeiter, 
                                kBV2RicoKalkQuotationOld.QuotationTakerId, kBV2RicoKalkQuotation.QuotationTakerId,
                                kBV2RicoKalkQuotationOld.QuotationTakerId, kBV2RicoKalkQuotation.QuotationTakerId);

                            oProtInfo.add(NDXKBVProtDetail::Angebot_BVBezeichnung, 
                                kBV2RicoKalkQuotationOld.KCS_KBVSubject, kBV2RicoKalkQuotation.KCS_KBVSubject,
                                kBV2RicoKalkQuotationOld.KCS_KBVSubject, kBV2RicoKalkQuotation.KCS_KBVSubject);

                            oProtInfo.add(NDXKBVProtDetail::Anfrage_Verfolg_AenderDatum, 
                                kBV2RicoKalkQuotationOld.Verfolg_AenderDatum, kBV2RicoKalkQuotation.Verfolg_AenderDatum,
                                date2str(kBV2RicoKalkQuotationOld.Verfolg_AenderDatum, 123, DateDay::Digits2, DateSeparator::Dot, DateMonth::Digits2, DateSeparator::Dot, DateYear::Digits4),
                                date2str(kBV2RicoKalkQuotation.Verfolg_AenderDatum, 123, DateDay::Digits2, DateSeparator::Dot, DateMonth::Digits2, DateSeparator::Dot, DateYear::Digits4));
                        }
                        nAnzProtPos += oProtInfo.write(this);
                    }

                    this.deleteNotUsedSalesQuotations(nDX_KBV2RicoKalkMapLoc);

                    SysInfologLevel sysInfologLevel = infolog.infologLevel();
                    infolog.setInfoLogLevel(SysInfologLevel::Error);
                    this.updatePotSalesVol(nDX_KBV2RicoKalkMapLoc.KBVBuildingProjectID);
                    infolog.setInfoLogLevel(sysInfologLevel);

                    if (nAnzProtPos)
                    {
                        if (nDX_KBV2RicoProtTable.validateWrite())
                        {
                            NDX_KBV2RicoProtTable nDX_KBV2RicoProtTableSave;
                            nDX_KBV2RicoProtTableSave.data(nDX_KBV2RicoProtTable);
                            nDX_KBV2RicoProtTable.updateFromNDXADO(nDXRicoKalkADO);
                            nDX_KBV2RicoProtTable.CounterDeleteStatement += nDX_KBV2RicoProtTableSave.CounterDeleteStatement;
                            nDX_KBV2RicoProtTable.CounterInsertStatement += nDX_KBV2RicoProtTableSave.CounterInsertStatement;
                            nDX_KBV2RicoProtTable.CounterUpdateStatement += nDX_KBV2RicoProtTableSave.CounterUpdateStatement;
                            nDX_KBV2RicoProtTable.write();
                        }
                        nDX_KBV2RicoProtTable.clear();
                    }
                    ttscommit;
                }
                catch
                {
                    ttsabort;
                    // logging
                    oProtInfo.parmProtID2(kBV2RicoKalkQuotation.QuotationId);
                    oProtInfo.add(NDXKBVProtDetail::Angebot_Abgleichfehler,
                                kBV2RicoKalkQuotation.QuotationId, kBV2RicoKalkQuotation.KBVBuildingProjectID ,
                                kBV2RicoKalkQuotation.QuotationId, kBV2RicoKalkQuotation.KBVBuildingProjectID , '', true);
                }
                finally
                {
                    oProtInfo.write(this);
                    oErrorMail.sendMessage();
                }
            }
        }
    }
    catch (ex)
    {
        error(ex.Message);
        withThrowError = true;
    }
    Info(strFmt("@NDXRicoBV:NDXNumberOfBuildingProjectsQuotations", anzBV, anzQuotation));
    Info(strFmt("@NDXRicoBV:NDXQuotationComparison", NDXHelperCommon::seconds2Str(), "@NDXBase:NDXEnd"));
    if (withThrowError)
    {
        throw error("@NDXRicoBV:NDXErrorRicoKalkQuotationTransfer");
    }
    return [anzBV, anzBVRico, anzQuotation];
}

/// <summary>
/// PaffH 05.02.24
/// </summary>
/// <param name = "_ndx_KBV2RicoKalkMap">NDX_KBV2RicoKalkMap</param>
/// <returns>counter deleted records</returns>
private int deleteNotUsedSalesQuotations(NDX_KBV2RicoKalkMap _ndx_KBV2RicoKalkMap)
{
    SalesQuotationTable salesQuotationTable;
    NDX_KBV2RicoProtTable lNDX_KBV2RicoProtTable;
    NDX_KBV2RicoProtLine lNDX_KBV2RicoProtLine;
    int anz;

    lNDX_KBV2RicoProtTable.clear();
    lNDX_KBV2RicoProtTable.KBVBuildingProjectID = _ndx_KBV2RicoKalkMap.KBVBuildingProjectID;
    lNDX_KBV2RicoProtTable.RicoKalkBVNr         = _ndx_KBV2RicoKalkMap.RicoKalkBVNr;
    lNDX_KBV2RicoProtTable.ProtKopfTyp          = NDXProtKopfTyp::RicoKalk_Angebot_Abgleich;
    lNDX_KBV2RicoProtTable.NewPublicate         = NDXKBV2RicoProtStatus::Cleanup;
    //lNDX_KBV2RicoProtTable.KBVProtID            = this.newGetNumNDXKBVProtId();
    lNDX_KBV2RicoProtTable.KBVProtIDInt         = NDX_KBV2RicoProtTable::getNextProtIdInt();


    while select forUpdate salesQuotationTable
    where salesQuotationTable.KCS_KBVBuildingProjectID == _ndx_KBV2RicoKalkMap.KBVBuildingProjectID
    {
        if(!this.checkRicoKalkSalesQuotationExists(salesQuotationTable,  _ndx_KBV2RicoKalkMap.RicoKalkBVNr))
        {
            anz++;
            ttsbegin;
            salesQuotationTable.delete();

            lNDX_KBV2RicoProtLine.clear();
            lNDX_KBV2RicoProtLine.KBVProtID     = lNDX_KBV2RicoProtTable.KBVProtID;
            lNDX_KBV2RicoProtLine.KBVProtIDInt  = lNDX_KBV2RicoProtTable.KBVProtIDInt;
            lNDX_KBV2RicoProtLine.KBVProtDetail = NDXKBVProtDetail::Angebot_AngebotNr;
            lNDX_KBV2RicoProtLine.ProtID2       = salesQuotationTable.QuotationId;
            lNDX_KBV2RicoProtLine.ValueOld      = salesQuotationTable.QuotationId;
            lNDX_KBV2RicoProtLine.ValueNew      = "@NDXRicoBV:NDXCleanUpQuotationDeleted";
            lNDX_KBV2RicoProtLine.write();
            ttscommit;
        }
    }
    if(anz > 0)
    {
        lNDX_KBV2RicoProtTable.write();
    }
    return anz;
}

/// <summary>
/// PaffH 05.02.24
/// </summary>
/// <param name = "kCS_KBVBuildingProjectID">KCS_KBVBuildingProjectID</param>
protected void updatePotSalesVol(KCS_KBVBuildingProjectID kCS_KBVBuildingProjectID)
{
    Args args = new Args();
    args.record(KCS_KBVBuildingProjectTable::find(kCS_KBVBuildingProjectID));
    args.caller(this);
    AVABPJobsController::newFromRico(args);
}

/// <summary>
/// PaffH 05.02.24
/// </summary>
/// <param name = "_salesQuotationTable">SalesQuotationTable</param>
/// <param name = "_currentcBVNr">NDXRicoKalkBVNr</param>
/// <param name = "_displayOnConsole">boolean</param>
/// <param name = "_textToDisplayOnConsole">str</param>
/// <returns>Salesquotation in RicoKalk exists</returns>
private boolean checkRicoKalkSalesQuotationExists(
    SalesQuotationTable _salesQuotationTable, 
    NDXRicoKalkBVNr _currentcBVNr, 
    boolean _displayOnConsole = false, 
    str _textToDisplayOnConsole = '')
{
    NDXRicoAbrufStr cAbruf;
    NDXRicoKalkBVNrStr RICBVNr;
    NDXRicoKalkBVNrStr cBVNr;
    boolean ret = true;

    if(_salesQuotationTable)
    {
        [RICBVNr, cAbruf] = NDXTokenizer::getTokenFromString(_salesQuotationTable.QuotationId, [1,2] , '.');
        NDXRicoAbruf abruf = str2int(cAbruf);

        [cBVNr] = NDXTokenizer::getTokenFromString(RICBVNr, [2] , '-');

        TblKalkKopf tblKalkKopf = nDXRicoKalkADO.selectTblKalkKopfFromBVNrAndAbrufAndRequestid(_currentcBVNr, abruf, _salesQuotationTable.KCS_KBVRequestID, _displayOnConsole, _textToDisplayOnConsole);
        if (tblKalkKopf.Abruf == 0)
        {
            ret = false;
        }
    }
    return ret;
}
